import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    // VFX throttling map
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 1. Diminishing Returns (DR) Decay
        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 2. Status Timer Ticks
        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 3. State Resolution & Priority Logic
        if (agent.banishTimer > 0) {
            agent.banished = true;
            agent.isMoving = false;
            agent.path = [];
            this.processStatusVFX(agent, dt, engine); // Early VFX process for banished
            return; 
        } else {
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE';
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            agent.setAnim(AnimState.STUN);
        } else if (agent.visualStatus === 'FROZEN') {
            agent.visualStatus = 'NONE';
        }

        if (agent.fearTimer > 0) {
            // FIX: Fear Logic Update
            // 只有在完全停止時才尋找新路徑，且尋找較遠的隨機點 (Range 2-3) 以避免原地抖動
            if (!agent.isMoving && agent.rootTimer <= 0) {
                // 擴大搜索半徑至 3 格，模擬驚慌亂跑
                const range = 3;
                const center = { q: agent.q, r: agent.r };
                const candidates = HexUtils.range(center, range).filter(h => {
                    // 排除自己腳下
                    if (h.q === center.q && h.r === center.r) return false;
                    // 必須是合法且無阻擋的地塊
                    return engine.map.isValid(h.q, h.r) && !engine.map.isBlocked(h.q, h.r, engine, agent.id);
                });

                if (candidates.length > 0) {
                    // 隨機選一個
                    const targetHex = candidates[Math.floor(Math.random() * candidates.length)];
                    // 使用 moveAgentToHex 且不設定射程限制 (0)，強制走到該點
                    engine.movement.moveAgentToHex(agent, targetHex, 0, engine, 1.4); // 稍微加速 (1.4x)
                }
            }
        }

        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        }

        if (!agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0 && agent.hp > 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }

        // 5. Visual Effects Tick (Loop for all states)
        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                // Standard Body Center height offset
                const pz = agent.physics.z + 45;
                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + pz
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('STUN', agent.stunTimer > 0);
        checkVFX('SILENCE', agent.silenceTimer > 0);
        checkVFX('FEAR', agent.fearTimer > 0);
        checkVFX('ROOT', agent.rootTimer > 0);
    }
}

import React, { useRef, useEffect, useCallback } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Skill, Role } from '../types';
import { useGameLoop } from '../hooks/useGameLoop';
import { useGameCamera } from '../hooks/useGameCamera';
import { useGameInput } from '../hooks/useGameInput';
import { useCameraControl } from '../hooks/useCameraControl';
import { Icons } from './ui/icons';
interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    winner: Team | null;
    rematch: () => void;
    nextLevel: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
    onOpenLogs: () => void;
}
const GameCanvas: React.FC<GameCanvasProps> = (props) => {
    const { 
        engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, 
        isShowcaseMode, spawnMode, draftRole, onSelect, winner, rematch, nextLevel, transitionPhase, onOpenLogs 
    } = props;
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const transitionProgress = useRef(0);
    const lastPhase = useRef(transitionPhase);
    const rendererRef = useRef<GameRenderer | null>(null);
    if (rendererRef.current === null) {
        rendererRef.current = new GameRenderer();
        engine.renderer = rendererRef.current;
    }
    const { camera, centerCamera, zoom } = useGameCamera(engine);
    useCameraControl({
        canvasRef, 
        cameraRef: camera,
        onZoom: zoom,
        engine 
    });
    const { pressedAgent, draggedObstacle, hoveredHexRef } = useGameInput({
        canvasRef, engine, rendererRef: rendererRef as React.MutableRefObject<GameRenderer>, cameraRef: camera,
        tool, selectedObstacle, hpInput, spawnMode, draftRole, winner,
        onSelect
    });
    useEffect(() => {
        if (transitionPhase !== lastPhase.current) {
            transitionProgress.current = 0;
            lastPhase.current = transitionPhase;
        }
    }, [transitionPhase]);
    const handleDraw = useCallback((ctx: CanvasRenderingContext2D, fps: number) => {
        if (!rendererRef.current) return;
        if (transitionPhase !== 'IDLE') {
            const dt = 1 / 60; 
            // FIX: Slower transition speed (0.8 -> 0.5) for weightier feel
            transitionProgress.current = Math.min(1.0, transitionProgress.current + dt * 0.5);
        } else {
            transitionProgress.current = 0;
        }
        rendererRef.current.setTransition(transitionProgress.current, transitionPhase); 
        const highlight = pressedAgent || selectedAgent || null;
        const currentHoverHex = hoveredHexRef.current;
        rendererRef.current.draw(
            ctx, 
            engine, 
            camera.current, 
            highlight, 
            fps, 
            currentHoverHex, 
            hoveredSkill
        );
        if (draggedObstacle && canvasRef.current) {
            const { type, px, py } = draggedObstacle;
            const { x, y, zoom: camZoom } = camera.current;
            const dpr = window.devicePixelRatio || 1;
            ctx.save();
            ctx.scale(dpr, dpr);
            const logicalW = canvasRef.current.width / dpr;
            const logicalH = canvasRef.current.height / dpr;
            ctx.translate(logicalW / 2, logicalH / 2);
            ctx.scale(camZoom, camZoom);
            ctx.translate(-x, -y); 
            const sprite = SpriteManager.getObstacleSprite(type, engine.mapConfig.layout);
            const liftOffset = 40; 
            ctx.shadowColor = 'rgba(0,0,0,0.5)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 30;
            ctx.globalAlpha = 0.9;
            ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
            ctx.restore();
        }
    }, [engine, transitionPhase, pressedAgent, selectedAgent, hoveredHexRef, hoveredSkill, draggedObstacle, camera]);
    const handleResize = useCallback((w: number, h: number) => {
        if (w > 0 && h > 0) {
            centerCamera(w, h);
        }
    }, [centerCamera]);
    const { fpsRef } = useGameLoop(
        engine, 
        canvasRef, 
        wrapperRef, 
        rendererRef, 
        handleDraw, 
        handleResize,
        camera
    );
    useEffect(() => {
        if (wrapperRef.current) {
            const t = setTimeout(() => {
                if (wrapperRef.current) {
                    centerCamera(wrapperRef.current.clientWidth, wrapperRef.current.clientHeight);
                }
            }, 100);
            return () => clearTimeout(t);
        }
    }, [engine.mapConfig.w, engine.mapConfig.h, isShowcaseMode, transitionPhase, centerCamera]);
    return (
        <div ref={wrapperRef} className="w-full h-full overflow-hidden relative bg-slate-950">
            <canvas 
                ref={canvasRef} 
                className="block w-full h-full"
                style={{ 
                    backgroundColor: engine.currentScene.background,
                    touchAction: 'none' 
                }} 
                onContextMenu={(e) => e.preventDefault()}
            />
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm z-50 pointer-events-auto">
                    <div className="text-center p-10 liquid-glass rounded-3xl animate-bounce-in max-w-lg w-full border border-white/10 shadow-[0_0_50px_rgba(0,0,0,0.8)]">
                        <div className="mb-6">
                            <span className="text-xs font-mono font-bold tracking-[0.5em] text-slate-400 uppercase block mb-2">Simulation Complete</span>
                            <h2 className={`text-5xl md:text-6xl font-black tracking-tighter ${winner === Team.BLUE ? 'text-blue-400 drop-shadow-[0_0_30px_rgba(59,130,246,0.6)]' : 'text-red-500 drop-shadow-[0_0_30px_rgba(239,68,68,0.6)]'}`}>
                                {winner === Team.BLUE ? 'IMPERIAL' : 'COVENANT'}
                            </h2>
                            <h2 className="text-4xl md:text-5xl font-black text-white tracking-widest mt-1 opacity-90">
                                VICTORY
                            </h2>
                        </div>
                        <div className="h-px w-24 mx-auto bg-white/20 rounded-full mb-8"></div>
                        <div className="flex flex-col gap-3">
                            <button 
                                onClick={nextLevel} 
                                className="liquid-btn-primary px-8 py-4 rounded-xl text-lg font-bold shadow-lg w-full flex items-center justify-center gap-3 group"
                            >
                                <Icons.Dice className="w-5 h-5 group-hover:scale-110 transition-transform" />
                                <span>前進下一關 (Next Level)</span>
                            </button>
                            <button 
                                onClick={onOpenLogs} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-slate-800/50 hover:bg-slate-700/50 border-white/10 text-cyan-400 shadow-md w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Log className="w-4 h-4 opacity-80 group-hover:scale-110 transition-transform" />
                                <span>戰鬥記錄 (Battle Logs)</span>
                            </button>
                            <button 
                                onClick={rematch} 
                                className="liquid-btn px-8 py-3 rounded-xl text-sm font-bold bg-white/5 hover:bg-white/10 border-white/10 text-slate-300 shadow-lg w-full flex items-center justify-center gap-2 group"
                            >
                                <Icons.Restart className="w-4 h-4 opacity-70 group-hover:opacity-100 group-hover:-rotate-90 transition-all" />
                                <span>再戰一局 (Rematch)</span>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};
export default GameCanvas;

import { useRef, useState, useCallback, useEffect } from 'react';
import { GameEngine, Agent } from '../engine/game';
import { ToolType, Team, Skill, Role, HexLayout } from '../types';
import { SCENE_DB } from '../data/scenes';
import { DesignExporter } from '../engine/systems/DesignExporter';
import { DEFAULT_HEX_LAYOUT } from '../constants';
export const useGameApp = () => {
    const engineRef = useRef(new GameEngine());
    const [isShowcaseMode, setIsShowcaseMode] = useState(true);
    const [isPlaying, setIsPlaying] = useState(false);
    const [unitCount, setUnitCount] = useState(0); 
    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);
    const [hpInput, setHpInput] = useState(600); 
    const [mapW, setMapW] = useState(12);
    const [mapH, setMapH] = useState(8);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);
    const [currentSceneId, setCurrentSceneId] = useState('VOID');
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);
    const [hexLayout, setHexLayout] = useState<HexLayout>(DEFAULT_HEX_LAYOUT);
    const [showLogs, setShowLogs] = useState(false);
    const [showDB, setShowDB] = useState(false);
    const [showVFXMap, setShowVFXMap] = useState(false); 
    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');
    const [showFactionWarning, setShowFactionWarning] = useState(false);
    useEffect(() => {
        const engine = engineRef.current;
        const handleGameOver = (data: { winner: Team }) => {
            setWinner(data.winner);
            if (engine.isRunning) engine.stop(); 
            setIsPlaying(false);
        };
        engine.bus.on('GAME_OVER', handleGameOver);
        return () => {
            engine.bus.off('GAME_OVER', handleGameOver);
        };
    }, []);
    useEffect(() => {
        if (isShowcaseMode && winner !== null) {
            const timer = setTimeout(() => {
                setTransitionPhase('OUT');
                engineRef.current.agents = [];
                // Fix: projectiles exists directly on GameEngine, not on the combat system.
                engineRef.current.projectiles = [];
                // Adjusted timers to match slower transition speed (0.5 factor)
                // 2.0s duration approx for transition 0->1
                setTimeout(() => {
                    setupShowcaseMap(); 
                    setTransitionPhase('IN'); 
                    setTimeout(() => {
                        setTransitionPhase('IDLE');
                        spawnShowcaseUnits(); 
                    }, 1800); // Increased from 1200
                }, 1800); // Increased from 1200
            }, 1000); 
            return () => clearTimeout(timer);
        }
    }, [winner, isShowcaseMode]);
    const setupShowcaseMap = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
        engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment(); 
        setCurrentSceneId(engine.currentScene.id);
    }, []);
    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const TARGET_PER_TEAM = 5;
        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

        const spawnTeam = (team: Team) => {
            let count = 0;
            while (count < TARGET_PER_TEAM && spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                // 依序分配職業，確保 5 個單位包含完整職業種類
                const role = roles[count % roles.length];
                const agent = engine.addAgent(team, h.q, h.r, hp, role);
                if (agent) count++;
            }
        };
        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);
        engine.play();
        setIsPlaying(true);
    }, []);
    const startShowcaseMatch = useCallback(() => {
        setupShowcaseMap();
        spawnShowcaseUnits();
    }, [setupShowcaseMap, spawnShowcaseUnits]);
    useEffect(() => {
        startShowcaseMatch();
    }, [startShowcaseMatch]);
    useEffect(() => {
        const interval = setInterval(() => {
            setUnitCount(engineRef.current.agents.length);
        }, 500); 
        return () => clearInterval(interval);
    }, []);
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);
    const enterManualMode = () => {
        setIsShowcaseMode(false);
        engineRef.current.stop();
        setIsPlaying(false);
        setWinner(null);
        engineRef.current.clear(true); 
        engineRef.current.agents = [];
        setUnitCount(0);
        setMapW(engineRef.current.mapConfig.w);
        setMapH(engineRef.current.mapConfig.h);
        setHexLayout(engineRef.current.mapConfig.layout);
        setCurrentSceneId(engineRef.current.currentScene.id);
    };
    const handleUpdateMapSize = useCallback((w: number, h: number) => {
        setMapW(w);
        setMapH(h);
        engineRef.current.mapConfig.w = w;
        engineRef.current.mapConfig.h = h;
        engineRef.current.clear(false); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);
    const handleUpdateLayout = useCallback((l: HexLayout) => {
        setHexLayout(l);
        engineRef.current.mapConfig.layout = l;
        engineRef.current.clear(true); 
        setSelectedAgent(null);
        setWinner(null);
    }, []);
    const handleSetScene = useCallback((id: string) => {
        const scene = SCENE_DB.find(s => s.id === id);
        if (scene) {
            engineRef.current.currentScene = scene;
            engineRef.current.map.rebuildMap(engineRef.current);
            setCurrentSceneId(id);
        }
    }, []);
    const handleRandomBattlefield = useCallback(() => {
        const engine = engineRef.current;
        engine.stop();
        setWinner(null);
        setSelectedAgent(null);
        engine.clear(false); 
        const newLayout: HexLayout = Math.random() > 0.5 ? 'FLAT' : 'POINTY';
        engine.mapConfig.layout = newLayout;
        setHexLayout(newLayout);
        engine.randomizeEnvironment();
        setMapW(engine.mapConfig.w);
        setMapH(engine.mapConfig.h);
        setCurrentSceneId(engine.currentScene.id);
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.hasObstacle(h.q, h.r));
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }
        let spawnIndex = 0;
        const TARGET_PER_TEAM = 5;
        const roles: Role[] = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];

        const spawnTeam = (team: Team) => {
            let count = 0;
            while (count < TARGET_PER_TEAM && spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                const role = roles[count % roles.length];
                const agent = engine.addAgent(team, h.q, h.r, hp, role);
                if (agent) count++;
            }
        };
        spawnTeam(Team.BLUE);
        spawnTeam(Team.RED);
        setIsPlaying(false); 
    }, []);
    const handleNextLevel = useCallback(() => {
        handleRandomBattlefield();
        const engine = engineRef.current;
        engine.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }, [handleRandomBattlefield]);
    const handleReset = useCallback(() => {
        engineRef.current.restart();
        setIsPlaying(false); 
        setWinner(null);
    }, []);
    const togglePlay = useCallback(() => {
        if (winner !== null) return;
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
            const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);
            if (!hasBlue || !hasRed) {
                setShowFactionWarning(true);
                setTimeout(() => setShowFactionWarning(false), 2500);
                return;
            }
            engineRef.current.play();
            setIsPlaying(true);
            setTool(ToolType.SELECT);
        }
    }, [isPlaying, winner]);
    const handleSelectAgent = (a: Agent | null) => {
        setSelectedAgent(a);
    };
    return {
        engineRef,
        state: {
            isShowcaseMode, isPlaying, unitCount, tool, selectedObstacle,
            selectedAgent, hoveredSkill, hpInput, mapW, mapH, timeScale,
            winner, currentSceneId, spawnMode, draftRole, showLogs, showDB, showVFXMap,
            transitionPhase, showFactionWarning, hexLayout
        },
        setters: {
            setTool, setSelectedObstacle, setHpInput, setTimeScale, 
            setSpawnMode, setDraftRole, setShowLogs, setShowDB, setShowVFXMap,
            setIsShowcaseMode, setSelectedAgent, setHoveredSkill
        },
        actions: {
            enterManualMode,
            handleUpdateMapSize,
            handleUpdateLayout,
            handleSetScene,
            handleRandomBattlefield,
            handleNextLevel,
            handleReset,
            togglePlay,
            onWin: (team: Team) => { engineRef.current.bus.emit('GAME_OVER', {winner: team}) },
            handleSelectAgent,
            startShowcaseMatch,
            downloadSpec: DesignExporter.downloadSpec,
            rematch: () => { 
                setWinner(null); 
                engineRef.current.restart(); 
                engineRef.current.play(); 
                setIsPlaying(true); 
            }
        }
    };
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {
    public static randomize(system: MapSystem, engine: GameEngine) {
        const layout = engine.mapConfig.layout;
        let cols, rows;

        if (layout === 'FLAT') {
            cols = 8 + Math.floor(Math.random() * 2); 
            rows = 10 + Math.floor(Math.random() * 2); 
        } else {
            cols = 7 + Math.floor(Math.random() * 2); 
            rows = 12 + Math.floor(Math.random() * 2); 
        }

        engine.mapConfig.w = cols; 
        engine.mapConfig.h = rows; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = Math.floor((W - 1) / 2);
        const centerR = Math.floor((H - 1) / 2);
        const centerHex = { q: centerQ, r: centerR };

        // 用於計算前景深度的參考值
        const centerSum = centerQ + centerR;

        const noisePhaseA = Math.random() * 1000;
        const noisePhaseB = Math.random() * 1000;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                const dist = HexUtils.dist({q, r}, centerHex);

                // 核心數學：階梯狀高度函數 (Stepped Height Field)
                // FIX: Increase amplitude from 2.0 to 3.5 for more height variation
                let rawVal = (Math.sin((q + noisePhaseA) * 0.45) + Math.cos((r + noisePhaseB) * 0.45)) * 3.5;

                // Steeper bowl edges
                rawVal += (dist * 0.8); 

                // 視覺修正：前景壓低 (防止遮擋戰場視線)
                // 根據 Diamond Grid 投影邏輯，(q+r) 越大表示越靠近螢幕下方 (前景)
                const visualDepth = (q + r) - centerSum;
                if (visualDepth > 0) {
                    // FIX: Relaxed penalty from 1.5 to 0.8 to allow some height in front
                    rawVal -= (visualDepth * 0.8); 
                    if (dist > 3) rawVal -= (dist * 0.3);
                }

                // 離散化為 Tier 層級
                let tier = Math.round(rawVal);
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

                // 確保中心區域平坦
                if (dist < 1.5) tier = 0;

                tiers.set(k, tier);
            }
        }

        // 高度場平滑
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let minN = tier;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) minN = Math.min(minN, tiers.get(nk)! + 1);
            });
            smoothedTiers.set(key, minN);
        });

        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);
        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        const centerHex = { q: Math.floor(W/2), r: Math.floor(H/2) };
        const keys = Array.from(system.getMapKeys());

        keys.forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const dist = HexUtils.dist({q, r}, centerHex);

            if (dist < 2.5) return; 
            if (engine.getAgentAt(q, r)) return;

            const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
            if (noise > 0.4 && Math.random() < 0.3) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    public hp: number = 100;
    public maxHp: number = 100;
    public shield: number = 0;
    public maxShield: number = 0;
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0;
    public moveSpeedMult: number = 1.0;
    public jump: number = 1;
    public weight: number = 1;
    public movementType: MovementType = MovementType.GROUND;

    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0;
    public curCDs: number[] = [0, 0, 0];

    public isMoving: boolean = false;
    public path: Hex[] = [];
    public trajectory: Hex[] = [];
    public moveProgress: number = 0;
    public facing: number = 1;
    public target: Agent | null = null;
    public targetHex: Hex | null = null;
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    // AI Loop Control
    public aiUpdateTimer: number = 0;
    public aiUpdateInterval: number = 0.3; // Default 300ms tick

    public trailHistory: {x: number, y: number, z: number}[] = [];

    public stunTimer: number = 0;
    public stunMax: number = 0;

    public banishTimer: number = 0;
    public banishMax: number = 0;

    public silenceTimer: number = 0;
    public silenceMax: number = 0;

    public banished: boolean = false;

    public rootTimer: number = 0;
    public fearTimer: number = 0;
    public tauntTimer: number = 0;
    public blindTimer: number = 0;
    public tauntTargetId: string | null = null;

    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    public drStacks: Record<string, number> = {};
    public drTimers: Record<string, number> = {};

    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public hitFlashTimer: number = 0;

    public physics = {
        x: 0, y: 0, z: 0,
        vx: 0, vy: 0, vz: 0,
        angle: 0, vAngle: 0
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR;
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        // Randomize AI tick to prevent frame spikes
        this.aiUpdateInterval = 0.2 + Math.random() * 0.2; 

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    setAnim(state: AnimState) {
        if (this.animState !== state && this.animState !== AnimState.DEAD) {
            this.animState = state;
        }
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.shield = 0;
        this.maxShield = 0;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
            this.movementType = stats.movementType;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0;
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.stunMax = 0;
        this.banishTimer = 0;
        this.banishMax = 0;
        this.silenceTimer = 0;
        this.silenceMax = 0;
        this.rootTimer = 0;
        this.fearTimer = 0;
        this.tauntTimer = 0;
        this.blindTimer = 0;
        this.tauntTargetId = null;

        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';

        this.drStacks = {};
        this.drTimers = {};

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5;

        this.target = null;
        this.targetHex = null;

        // Reset AI
        this.aiUpdateTimer = Math.random() * 0.5;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
        this.trailHistory = [];
    }
}

import { Agent, GameEngine } from "../game";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,

    "HasTarget": (a, engine) => {
        // AI Throttling: 只有當計時器歸零，才進行昂貴的目標掃描
        // 使用 engine.timeScale 確保在加速/減速時 AI 頻率一致
        // 但 tick 傳入的是 dt，我們需要一個簡單的累加器

        // 注意：BTNode.tick 是每幀調用。我們在這裡處理頻率控制。
        // 但這裡無法獲取 dt。dt 由 GameEngine.tick 處理，我們假設 Agent.aiUpdateTimer 在 ControlSystem 或 AISystem 中被更新?
        // 修正：我們直接在這裡讀取 engine.battleTime 進行差分比較太複雜。
        // 最佳解：在 GameEngine 的 loop 中更新 agent.aiUpdateTimer。
        // 由於我們不能修改 engine loop，我們利用 behaviorTree 的 tick 頻率。

        // 為了簡單起見，我們使用 performance.now 的差值作為降頻策略，或者直接依賴 Agent 內部的計數器
        // 假設 Agent.ts 已經有 aiUpdateTimer 屬性，我們需要在某個 System 中減少它。
        // 為了不依賴外部 System 更新，我們可以在這裡用一個近似值，或者更聰明地：
        // 在 ControlSystem.update 中統一扣除 agent.aiUpdateTimer。

        if (a.aiUpdateTimer <= 0 || !a.target || a.target.hp <= 0 || a.target.banished) {
            engine.updateTarget(a);
            a.aiUpdateTimer = a.aiUpdateInterval; // Reset timer
        }

        return a.target !== null;
    },

    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;

        const isOnCD = a.curCDs[idx] > 0.01; 
        if (isOnCD || a.mp < s.cost) return false;
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;

        // 沉默邏輯：沉默時無法使用非普攻
        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;

        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        const perceptionBonus = (skill.tag === 'ULT') ? 5 : 2;
        const visionRange = skill.range + perceptionBonus;

        const result = engine.calculateOptimalTarget(a, skill);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            const dist = HexUtils.dist(a, result.targetAgent);
            // 只有在視野範圍內才鎖定
            return dist <= visionRange;
        } else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.getEffectiveRange(a, tQ, tR, skill.range);
        const dist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);

        return dist <= effRange;
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        // 待機時停止移動，防止滑步
        if (a.isMoving) {
            a.isMoving = false;
            a.path = [];
        }
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.initiateCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;

        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;

        // 目標點驗證
        let dest = null;
        if (a.targetHex) dest = a.targetHex;
        else if (a.target) dest = {q: a.target.q, r: a.target.r};

        if (dest) {
            return engine.moveAgentToHex(a, dest, skill.range, speedMult);
        }
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;

        // 容錯：如果 Chase 時沒有目標，強制掃描一次 (無視 Timer)
        if (!a.target) engine.updateTarget(a); 
        if (!a.target) return NodeState.FAILURE;

        const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
        a.btStatus = `鎖定 ${a.target.id}`;

        return engine.moveAgentToHex(a, {q: a.target.q, r: a.target.r}, skill.range, speedMult);
    }
};

import { Agent, GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {
    /**
     * 計算有效射程（考慮高地加成）
     */
    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);
        const deltaH = h1 - h2;
        const heightBonus = deltaH > 0 ? Math.floor(deltaH / BLOCK_HEIGHT * 0.5) : 0;
        return baseRange + heightBonus;
    }

    /**
     * RTS 等級目標選取評分 - V2.0 修正版
     * 解決「近身不打、跑去打遠處法師」的問題
     */
    public updateTarget(a: Agent, engine: GameEngine) {
        // 如果當前目標已經死亡或無效，先清除
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;

        let maxScore = -Infinity;
        let bestTarget: Agent | null = null;

        // 如果被嘲諷，強制鎖定嘲諷來源
        if (a.tauntTimer > 0 && a.tauntTargetId) {
            const taunter = engine.agents.find(ag => ag.id === a.tauntTargetId);
            if (taunter && taunter.hp > 0 && !taunter.banished) {
                a.target = taunter;
                return;
            }
        }

        const isSilenced = a.silenceTimer > 0;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const dist = Math.max(0.5, HexUtils.dist(a, o));

                // 1. 距離權重 (Exponential Falloff)
                // 修正：極大幅度提高近距離權重
                // Dist 1 => 2000
                // Dist 5 => 333
                // Dist 10 => 181
                const distScore = 2000 / (dist + 0.5); 

                // 2. 血量權重 (殘血優先)
                // 0 ~ 50 分
                const hpScore = (1 - o.hp / o.maxHp) * 50;

                // 3. 威脅權重 (Threat)
                // 只有在未被沉默時才考慮打斷
                let threatScore = 0;
                if (!isSilenced && o.castingSkillIdx !== -1) {
                    const castingSkill = o.skills[o.castingSkillIdx];
                    if (castingSkill?.tag === 'ULT') {
                        threatScore = 200; 
                    } else if (castingSkill?.tag === 'ACTIVE') {
                        threatScore = 50; 
                    }
                }

                // 4. 黏著加分 (Hysteresis)
                // 如果是當前目標，給予加分以避免頻繁切換 (防抖)
                const stickyBonus = (a.target === o) ? 300 : 0;

                // 總分計算
                const score = distScore + hpScore + threatScore + stickyBonus;

                if (score > maxScore) {
                    maxScore = score;
                    bestTarget = o;
                }
            }
        }
        a.target = bestTarget;
    }

    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        // AOE 邏輯保持不變，因為它是基於覆蓋率計算
        if (skill.type === 'AOE') {
            return this.findBestAOELocation(source, skill, engine);
        }

        // 單體技能：如果沒有目標，或目標無效，強制刷新
        if (!source.target || source.target.hp <= 0 || source.target.banished) {
            this.updateTarget(source, engine);
        }
        return { targetAgent: source.target, targetHex: null };
    }

    public getImpactArea(source: Agent, targetHex: Hex, skill: Skill, engine: GameEngine): Hex[] {
        if (skill.type === 'AOE') {
            const radius = skill.aoeRadius || 1;
            return HexUtils.range(targetHex, radius).filter(h => engine.map.isValid(h.q, h.r));
        }
        return [targetHex];
    }

    private findBestAOELocation(source: Agent, skill: Skill, engine: GameEngine) {
        const range = skill.range;
        const radius = skill.aoeRadius || 1;
        const enemies = engine.agents.filter(e => e.team !== source.team && e.hp > 0 && !e.banished);

        if (enemies.length === 0) return { targetAgent: null, targetHex: null };

        let bestHex: Hex | null = null;
        let maxImpact = -1;

        // 優化搜索空間：只檢查敵人的位置及其周圍
        const candidates = new Set<string>();
        enemies.forEach(e => {
            candidates.add(HexUtils.key(e));
            // 只有在大範圍 AOE 時才檢查周圍空地
            if (radius > 1) {
                HexUtils.neighbors(e).forEach(n => candidates.add(HexUtils.key(n)));
            }
        });

        candidates.forEach(key => {
            const [q, r] = key.split(',').map(Number);
            const targetHex = { q, r };
            if (!engine.map.isValid(q, r)) return;

            // 距離檢查
            if (HexUtils.dist(source, targetHex) > this.getEffectiveRange(source, q, r, range, engine)) return;

            let impact = 0;
            enemies.forEach(e => {
                if (HexUtils.dist(targetHex, e) <= radius) {
                    const weight = (e.castingSkillIdx !== -1 && e.skills[e.castingSkillIdx]?.tag === 'ULT') ? 5.0 : 1.0;
                    impact += weight * (1.0 + (1 - e.hp/e.maxHp));
                }
            });

            if (impact > maxImpact) {
                maxImpact = impact;
                bestHex = targetHex;
            }
        });

        return { targetAgent: null, targetHex: bestHex };
    }
}

import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    // VFX throttling map
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 0. AI Tick Update (System-wide clock for the agent)
        if (agent.aiUpdateTimer > 0) {
            agent.aiUpdateTimer -= dt;
        }

        // 1. Diminishing Returns (DR) Decay
        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 2. Status Timer Ticks
        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 3. State Resolution & Priority Logic
        if (agent.banishTimer > 0) {
            agent.banished = true;
            agent.isMoving = false;
            agent.path = [];
            this.processStatusVFX(agent, dt, engine); // Early VFX process for banished
            return; 
        } else {
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE';
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            agent.setAnim(AnimState.STUN);
        } else if (agent.visualStatus === 'FROZEN') {
            agent.visualStatus = 'NONE';
        }

        if (agent.fearTimer > 0) {
            // FIX: Fear Logic Update
            // 只有在完全停止時才尋找新路徑，且尋找較遠的隨機點 (Range 2-3) 以避免原地抖動
            if (!agent.isMoving && agent.rootTimer <= 0) {
                // 擴大搜索半徑至 3 格，模擬驚慌亂跑
                const range = 3;
                const center = { q: agent.q, r: agent.r };
                const candidates = HexUtils.range(center, range).filter(h => {
                    // 排除自己腳下
                    if (h.q === center.q && h.r === center.r) return false;
                    // 必須是合法且無阻擋的地塊
                    return engine.map.isValid(h.q, h.r) && !engine.map.isBlocked(h.q, h.r, engine, agent.id);
                });

                if (candidates.length > 0) {
                    // 隨機選一個
                    const targetHex = candidates[Math.floor(Math.random() * candidates.length)];
                    // 使用 moveAgentToHex 且不設定射程限制 (0)，強制走到該點
                    engine.movement.moveAgentToHex(agent, targetHex, 0, engine, 1.4); // 稍微加速 (1.4x)
                }
            }
        }

        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        }

        if (!agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0 && agent.hp > 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }

        // 5. Visual Effects Tick (Loop for all states)
        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                // Standard Body Center height offset
                const pz = agent.physics.z + 45;
                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + pz
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('STUN', agent.stunTimer > 0);
        checkVFX('SILENCE', agent.silenceTimer > 0);
        checkVFX('FEAR', agent.fearTimer > 0);
        checkVFX('ROOT', agent.rootTimer > 0);
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, MovementType } from "../../types";
import { HexUtils, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";
import { OBSTACLE_DB } from "../../data/obstacles";
import { TargetingSystem } from "./TargetingSystem";

interface PQNode {
    hash: number;
    priority: number;
}

export class Pathfinder {
    private _gScore = new Map<number, number>();
    private _cameFrom = new Map<number, number>();
    private _pq: PQNode[] = [];

    public findPath(startAgent: Agent, endQ: number, endR: number, range: number, ignoreUnits: boolean, engine: GameEngine, targeting: TargetingSystem): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);
        const goalHex = { q: endQ, r: endR };

        // 射程檢查：若已在動態射程內，則無需移動
        const effRange = targeting.getEffectiveRange(startAgent, endQ, endR, range, engine);
        if (HexUtils.dist(startAgent, goalHex) <= effRange) return [];

        this._gScore.clear();
        this._cameFrom.clear();
        this._pq = [];

        this._gScore.set(startH, 0);
        this.pqPush(startH, 0);

        let iterations = 0;
        let bestH = -1;
        const MAX_ITER = 600; 

        while (this._pq.length > 0 && iterations < MAX_ITER) {
            iterations++;
            const current = this.pqPop()!;
            const currentHex = HexUtils.unhash(current.hash);

            // 成功判定：進入有效射程
            if (HexUtils.dist(currentHex, goalHex) <= targeting.getEffectiveRange(currentHex, endQ, endR, range, engine)) {
                bestH = current.hash;
                break;
            }

            for (let i = 0; i < 6; i++) {
                const neighborH = current.hash + NEIGHBOR_HASH_OFFSETS[i];
                if (!engine.map.isValidHash(neighborH)) continue;

                // 物理碰撞判定
                if (engine.map.hasObstacleHash(neighborH)) {
                    const type = engine.map.obstacles.get(HexUtils.key(HexUtils.unhash(neighborH)));
                    const def = OBSTACLE_DB[type || 'WALL'];
                    if (startAgent.movementType === MovementType.FLYING ? def?.blocksFlying : def?.blocksMovement) continue;
                }

                if (!ignoreUnits) {
                    const occ = engine.agentMap.get(neighborH);
                    if (occ && occ.hp > 0 && occ !== startAgent) continue;
                }

                // 數學地勢成本計算 (Asymmetric Verticality)
                const nHex = HexUtils.unhash(neighborH);
                let moveCost = 1.0;

                if (startAgent.movementType !== MovementType.FLYING) {
                    const h1 = engine.map.getTerrainHeight(currentHex.q, currentHex.r);
                    const h2 = engine.map.getTerrainHeight(nHex.q, nHex.r);

                    const deltaH = h2 - h1; // Target - Current
                    const jumpLimit = Math.max(1, startAgent.jump) * BLOCK_HEIGHT;

                    // 1. 向上攀爬 (Climbing Up)：嚴格檢定
                    if (deltaH > jumpLimit) continue; 

                    // 2. 向下跳躍 (Jumping Down)：允許任何高度 (物理引擎會處理傷害)
                    // 無需檢查 deltaH < -jumpLimit

                    // Cost Calculation
                    if (deltaH > 0) {
                        // 上坡成本：隨高度增加
                        moveCost += deltaH / BLOCK_HEIGHT * 0.5; 
                    } else {
                        // 下坡/跳崖成本：固定小額成本 (不隨深度增加，否則 AI 會不敢跳崖)
                        // 給予微小懲罰讓 AI 優先選擇平地，但非阻斷性
                        moveCost += 0.2;
                    }
                }

                const tentativeG = (this._gScore.get(current.hash) || 0) + moveCost;

                if (!this._gScore.has(neighborH) || tentativeG < this._gScore.get(neighborH)!) {
                    this._cameFrom.set(neighborH, current.hash);
                    this._gScore.set(neighborH, tentativeG);

                    // 核心數學：六邊形 Cube 曼哈頓距離啟發函數
                    const hCost = HexUtils.dist(nHex, goalHex);
                    this.pqPush(neighborH, tentativeG + hCost);
                }
            }
        }

        return bestH !== -1 ? this.reconstructPath(bestH, startH) : [];
    }

    private pqPush(hash: number, priority: number) {
        this._pq.push({ hash, priority });
        // 生產環境應使用 Binary Heap，此處使用排序模擬
        this._pq.sort((a, b) => a.priority - b.priority); 
    }

    private pqPop() { return this._pq.shift(); }

    private reconstructPath(current: number, startH: number): Hex[] {
        const path: Hex[] = [];
        let curr = current;
        while (curr !== startH && path.length < 100) {
            path.push(HexUtils.unhash(curr));
            curr = this._cameFrom.get(curr) || -1;
        }
        return path.reverse();
    }
}

import { Agent, GameEngine } from "../../game";
import { HexUtils, Vector } from "../../utils";
import { MovementType } from "../../../types";
import { BLOCK_HEIGHT } from "../../../constants";

/**
 * Robust Anti-Stacking System
 * Resolves accidental overlaps (from skills/physics) by expelling units to valid neighbors.
 */
export class StackingResolver {

    public resolve(engine: GameEngine) {
        const cellMap = new Map<number, Agent[]>();

        // 1. Group by logical coordinates
        for (const a of engine.agents) {
            if (a.hp <= 0 || a.banished) continue;
            const h = HexUtils.hash(a.q, a.r);
            if (!cellMap.has(h)) cellMap.set(h, []);
            cellMap.get(h)!.push(a);
        }

        // 2. Resolve multi-unit cells
        cellMap.forEach((occupants, hash) => {
            if (occupants.length > 1) {
                this.expelExcess(occupants, hash, engine);
            }
        });
    }

    private expelExcess(list: Agent[], hash: number, engine: GameEngine) {
        // Sort: Stationary units are "owners", moving units are "guests"
        list.sort((a, b) => (a.isMoving ? 1 : 0) - (b.isMoving ? 0 : 1));

        const owner = list[0];
        const currentH = engine.map.getTerrainHeight(owner.q, owner.r);

        for (let i = 1; i < list.length; i++) {
            const guest = list[i];
            const found = this.findExpulsionSpot(guest, currentH, engine);

            if (found) {
                // Perform Logical Displacement
                engine.updateAgentPosition(guest, found.q, found.r);

                // Clear active move to prevent pathing glitches
                if (guest.isMoving) {
                    guest.isMoving = false;
                    guest.path = [];
                }

                // Add small physical impulse to separate visually
                const dir = Vector.normalize(Vector.sub(
                    HexUtils.toPx(found.q, found.r, engine.mapConfig), 
                    HexUtils.toPx(owner.q, owner.r, engine.mapConfig)
                ));
                guest.physics.vx += dir.x * 200;
                guest.physics.vy += dir.y * 200;

                engine.log(guest, 'SYSTEM', '擠出', `從 (${owner.q},${owner.r})`, '解決重疊狀態');
            }
        }
    }

    private findExpulsionSpot(agent: Agent, sourceH: number, engine: GameEngine) {
        // Spiral-like search: Check nearest neighbors first
        const neighbors = HexUtils.neighbors(agent);

        // Shuffle to avoid directional bias
        for (let i = neighbors.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
        }

        for (const n of neighbors) {
            // Check basic validity
            if (!engine.map.isValid(n.q, n.r)) continue;

            // Check if already blocked by static or dynamic
            if (engine.map.isBlocked(n.q, n.r, engine, agent.id)) continue;

            // Height Safety Check - Modified for "Jump Down"
            if (agent.movementType === MovementType.GROUND) {
                const nH = engine.map.getTerrainHeight(n.q, n.r);
                const deltaH = nH - sourceH;
                const jumpLimit = Math.max(1, agent.jump) * BLOCK_HEIGHT;

                // Block if trying to climb UP too high
                if (deltaH > jumpLimit) continue;

                // Allow falling down regardless of height (pushed off cliff)
            }

            return n;
        }
        return null;
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {
    /**
     * 計算有效射程（考慮高地加成）
     */
    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);
        const deltaH = h1 - h2;
        const heightBonus = deltaH > 0 ? Math.floor(deltaH / BLOCK_HEIGHT * 0.5) : 0;
        return baseRange + heightBonus;
    }

    /**
     * RTS 等級目標選取評分 - V2.0 修正版
     * 解決「近身不打、跑去打遠處法師」的問題
     */
    public updateTarget(a: Agent, engine: GameEngine) {
        // 如果當前目標已經死亡或無效，先清除
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;

        let maxScore = -Infinity;
        let bestTarget: Agent | null = null;

        // 如果被嘲諷，強制鎖定嘲諷來源
        if (a.tauntTimer > 0 && a.tauntTargetId) {
            const taunter = engine.agents.find(ag => ag.id === a.tauntTargetId);
            if (taunter && taunter.hp > 0 && !taunter.banished) {
                a.target = taunter;
                return;
            }
        }

        const isSilenced = a.silenceTimer > 0;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const dist = Math.max(0.5, HexUtils.dist(a, o));

                // 1. 距離權重 (Exponential Falloff)
                // 修正：極大幅度提高近距離權重
                const distScore = 2000 / (dist + 0.5); 

                // 2. 血量權重 (殘血優先)
                const hpScore = (1 - o.hp / o.maxHp) * 50;

                // 3. 威脅權重 (Threat)
                let threatScore = 0;
                if (!isSilenced && o.castingSkillIdx !== -1) {
                    const castingSkill = o.skills[o.castingSkillIdx];
                    if (castingSkill?.tag === 'ULT') {
                        threatScore = 200; 
                    } else if (castingSkill?.tag === 'ACTIVE') {
                        threatScore = 50; 
                    }
                }

                // 4. 黏著加分 (Hysteresis)
                // 如果是當前目標，給予加分以避免頻繁切換 (防抖)
                const stickyBonus = (a.target === o) ? 300 : 0;

                // 總分計算
                const score = distScore + hpScore + threatScore + stickyBonus;

                if (score > maxScore) {
                    maxScore = score;
                    bestTarget = o;
                }
            }
        }
        a.target = bestTarget;
    }

    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        // AOE 邏輯保持不變
        if (skill.type === 'AOE') {
            return this.findBestAOELocation(source, skill, engine);
        }

        // 單體技能優化：黏著邏輯
        // 如果當前目標有效且在射程內，直接鎖定，不要嘗試移動尋找「更好」的位置
        if (source.target && source.target.hp > 0 && !source.target.banished) {
            const effRange = this.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
            if (HexUtils.dist(source, source.target) <= effRange) {
                return { targetAgent: source.target, targetHex: null };
            }
        }

        // 如果沒有目標，或目標無效，或目標超出射程，才刷新
        this.updateTarget(source, engine);
        return { targetAgent: source.target, targetHex: null };
    }

    public getImpactArea(source: Agent, targetHex: Hex, skill: Skill, engine: GameEngine): Hex[] {
        if (skill.type === 'AOE') {
            const radius = skill.aoeRadius || 1;
            return HexUtils.range(targetHex, radius).filter(h => engine.map.isValid(h.q, h.r));
        }
        return [targetHex];
    }

    private findBestAOELocation(source: Agent, skill: Skill, engine: GameEngine) {
        const range = skill.range;
        const radius = skill.aoeRadius || 1;
        const enemies = engine.agents.filter(e => e.team !== source.team && e.hp > 0 && !e.banished);

        if (enemies.length === 0) return { targetAgent: null, targetHex: null };

        let bestHex: Hex | null = null;
        let maxImpact = -1;

        const candidates = new Set<string>();
        enemies.forEach(e => {
            candidates.add(HexUtils.key(e));
            if (radius > 1) {
                HexUtils.neighbors(e).forEach(n => candidates.add(HexUtils.key(n)));
            }
        });

        candidates.forEach(key => {
            const [q, r] = key.split(',').map(Number);
            const targetHex = { q, r };
            if (!engine.map.isValid(q, r)) return;

            if (HexUtils.dist(source, targetHex) > this.getEffectiveRange(source, q, r, range, engine)) return;

            let impact = 0;
            enemies.forEach(e => {
                if (HexUtils.dist(targetHex, e) <= radius) {
                    const weight = (e.castingSkillIdx !== -1 && e.skills[e.castingSkillIdx]?.tag === 'ULT') ? 5.0 : 1.0;
                    impact += weight * (1.0 + (1 - e.hp/e.maxHp));
                }
            });

            if (impact > maxImpact) {
                maxImpact = impact;
                bestHex = targetHex;
            }
        });

        return { targetAgent: null, targetHex: bestHex };
    }
}

import { Agent, GameEngine } from "../game";
import { NodeState } from "../../types";
import { HexUtils } from "../utils";

export type BTConditionFn = (agent: Agent, engine: GameEngine, args?: any) => boolean;
export type BTActionFn = (agent: Agent, engine: GameEngine, args?: any) => NodeState;

export const BTConditions: Record<string, BTConditionFn> = {
    "IsDead": (a) => a.hp <= 0,
    "IsAlive": (a) => a.hp > 0,
    "IsStunned": (a) => a.stunTimer > 0,
    "IsBanished": (a) => a.banishTimer > 0,
    "IsSilenced": (a) => a.silenceTimer > 0,

    "HasTarget": (a, engine) => {
        // Sticky Targeting V2:
        // 如果當前有有效目標，且未被放逐/死亡，直接返回 True。
        // 不再受 aiUpdateTimer 限制，防止在攻擊間隙丟失目標。
        if (a.target && a.target.hp > 0 && !a.target.banished) {
            // 只有在真的需要切換目標（例如嘲諷）時才強制檢查
            if (a.tauntTimer > 0 && a.tauntTargetId !== a.target.id) {
                // Let fall through to update logic
            } else {
                return true; 
            }
        }

        // 只有當「沒有目標」或者「Timer 歸零」時才掃描
        if (a.aiUpdateTimer <= 0 || !a.target || a.target.hp <= 0) {
            engine.updateTarget(a);
            a.aiUpdateTimer = a.aiUpdateInterval; // Reset timer
        }

        return a.target !== null;
    },

    "HpBelow": (a, _, args) => (a.hp / a.maxHp) < args.threshold,
    "MpAbove": (a, _, args) => a.mp >= args.amount,

    "SkillReady": (a, _, args) => {
        const idx = args.slot; 
        const s = a.skills[idx];
        if (!s) return false;

        // CD Tolerance Optimization:
        // 普攻 (BASIC) 允許 0.2s 的預熱時間。
        // 這意味著如果 CD 還剩 0.15s，我們也視為 Ready，開始進入 Cast 流程 (播放動畫)。
        // 當動畫播放到判定點時，CD 已經轉好了。這能完美填充垃圾時間。
        const tolerance = (s.tag === 'BASIC') ? 0.2 : 0.01;
        const isOnCD = a.curCDs[idx] > tolerance; 

        if (isOnCD || a.mp < s.cost) return false;
        if (a.stunTimer > 0 || a.banished || a.fearTimer > 0) return false;

        if (a.silenceTimer > 0 && s.tag !== 'BASIC') return false;

        return true;
    },

    "FindOptimalTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        const perceptionBonus = (skill.tag === 'ULT') ? 5 : 2;
        const visionRange = skill.range + perceptionBonus;

        const result = engine.calculateOptimalTarget(a, skill);

        if (result.targetAgent) {
            a.target = result.targetAgent;
            a.targetHex = null;
            const dist = HexUtils.dist(a, result.targetAgent);
            return dist <= visionRange;
        } else if (result.targetHex) {
            a.target = null;
            a.targetHex = result.targetHex;
            return true;
        }
        return false;
    },

    "IsTargetInRange": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return false;

        let tQ = 0, tR = 0;
        if (a.targetHex) { tQ = a.targetHex.q; tR = a.targetHex.r; }
        else if (a.target) { tQ = a.target.q; tR = a.target.r; }
        else return false;

        const effRange = engine.getEffectiveRange(a, tQ, tR, skill.range);
        const dist = a.targetHex ? HexUtils.dist(a, a.targetHex) : HexUtils.dist(a, a.target!);

        // 寬鬆判定：允許 0.1 的誤差，避免因為浮點數距離導致的「在邊緣不攻擊」
        return dist <= (effRange + 0.1);
    }
};

export const BTActions: Record<string, BTActionFn> = {
    "Wait": (a, engine, args) => {
        a.btStatus = args.status || "等待";
        return NodeState.RUNNING;
    },
    "Idle": (a) => {
        a.btStatus = "待機中";
        if (a.isMoving) {
            a.isMoving = false;
            a.path = [];
        }
        return NodeState.SUCCESS;
    },
    "CastSkill": (a, engine, args) => {
        const idx = args.slot;
        return engine.initiateCast(a, idx);
    },
    "MoveToOptimal": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;

        const speedMult = (skill.tag === 'ULT') ? 1.3 : 1.0;

        let dest = null;
        if (a.targetHex) dest = a.targetHex;
        else if (a.target) dest = {q: a.target.q, r: a.target.r};

        if (dest) {
            return engine.moveAgentToHex(a, dest, skill.range, speedMult);
        }
        return NodeState.FAILURE;
    },
    "ChaseTarget": (a, engine, args) => {
        const idx = args.slot;
        const skill = a.skills[idx];
        if (!skill) return NodeState.FAILURE;

        // 容錯：Chase 時強制獲取目標，不依賴 Timer
        if (!a.target) engine.updateTarget(a); 
        if (!a.target) return NodeState.FAILURE;

        const speedMult = (skill.tag === 'ULT') ? 1.4 : 1.1;
        a.btStatus = `鎖定 ${a.target.id}`;

        return engine.moveAgentToHex(a, {q: a.target.q, r: a.target.r}, skill.range, speedMult);
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 30; 
const EXPANSION_BIAS = 0.6; // 數學膨脹量 (px)，解決縫隙

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 1. 物理座標取整
        const drawX = Math.floor(x);

        // 2. 呼吸戰場算法 (Breathing Terrain Math)
        // 使用座標 (x, y) 作為種子，創造具有空間連續性的波動
        // 頻率 1.5，振幅 4px，加上基於位置的相位偏移
        const floatOffset = Math.sin(globalTime * 1.5 + (x * 0.01) + (y * 0.01)) * 4;

        // 3. 視覺頂面 Y 軸 (相對於 drawY)
        // 將呼吸偏移量應用於高度，使地塊看起來在懸浮
        const visualTopY = -Math.floor(height) + floatOffset;

        const drawY = Math.floor(y);

        // 膨脹幾何半徑
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        // 4. 繪製基座與側牆 (Pedestal & Walls)
        const drawFace = (idx1: number, idx2: number, color: string, isLightSide: boolean) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            // 漸層側牆 (增加立體感)
            const grad = ctx.createLinearGradient(0, visualTopY, 0, PEDESTAL_DEPTH);
            grad.addColorStop(0, color);
            grad.addColorStop(1, isLightSide ? theme.sideDark : '#020617'); // 底部漸黑，融入背景

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY); // Top-Left
            ctx.lineTo(v2.x, v2.y + visualTopY); // Top-Right
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH); // Bottom-Right (Deep)
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH); // Bottom-Left (Deep)
            ctx.closePath();
            ctx.fill();

            // 側邊高光稜線 (Rim Light)
            ctx.strokeStyle = 'rgba(255,255,255,0.08)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH);
            ctx.stroke();

            // 頂部接縫高光
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + visualTopY);
            ctx.strokeStyle = 'rgba(255,255,255,0.15)';
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            drawFace(1, 0, theme.sideDark, false);  // Right-Bottom
            drawFace(2, 1, theme.sideLight, true); // Bottom (Lightest)
            drawFace(3, 2, theme.sideDark, false);  // Left-Bottom
        } else {
            drawFace(1, 0, theme.sideDark, false);  // Right Side
            drawFace(2, 1, theme.sideLight, true); // Left Side
        }

        // 5. 繪製頂部 (Top Cap)
        ctx.translate(0, visualTopY);

        // 頂面材質光澤
        const topGrad = ctx.createLinearGradient(-r, -r, r, r);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5; // 加粗一點
        ctx.globalAlpha = 0.6;
        ctx.stroke();

        // 6. 特殊地表 (岩漿流動)
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // 重算呼吸偏移，確保裝飾物跟隨地塊浮動
        const globalTime = Date.now() / 1000; // 近似取值，或者應從參數傳入。此處為簡化直接取系統時。
        // 若要精確同步，應在 drawBlock 計算後回傳 visualTopY 或傳入 time。
        // 這裡重新計算一次偏移量以保持無狀態。
        const floatOffset = Math.sin(globalTime * 1.5 + (baseX * 0.01) + (baseY * 0.01)) * 4;

        const visualY = Math.floor(baseY) - Math.floor(height) + floatOffset;

        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Rebuild Static Background Layer (Gradient + Stars + Mountains)
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Draw Dynamic Atmospheric Elements
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // A. Deep Background Gradient (Richer)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.4, scene.fogColor); 
        bgGrad.addColorStop(1, scene.horizon); 
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // B. Scene Specific Static Features
        if (scene.bgFeature === 'SKY_RIVER') {
            this.drawStaticSkyRiver(ctx, w, h);
        } else {
            this.drawStaticStars(ctx, w, h, 150); // More stars
        }

        // C. Distant Grid (Retro-wave floor)
        this.drawPerspectiveGrid(ctx, w, h, scene.horizon);

        // D. Mountains / Dunes
        if (scene.bgFeature === 'DUNES') {
            this.drawStaticDunes(ctx, w, h, scene.horizon, scene.fogColor);
        } else {
            this.drawStaticMountains(ctx, w, h, scene.horizon, scene.fogColor);
        }

        // E. Vignette
        const rad = Math.max(w, h);
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad * 0.9);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,0,0,0.8)'); // Darker vignette
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawPerspectiveGrid(ctx: CanvasRenderingContext2D, w: number, h: number, color: string) {
        ctx.save();
        ctx.globalAlpha = 0.1;
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;

        const horizonY = h * 0.6;
        const centerX = w * 0.5;

        // Vertical lines converging to horizon
        ctx.beginPath();
        for (let x = -w; x < w * 2; x += 100) {
            ctx.moveTo(x, h);
            ctx.lineTo(centerX + (x - centerX) * 0.1, horizonY);
        }
        ctx.stroke();

        // Horizontal lines
        ctx.beginPath();
        for (let y = h; y > horizonY; y -= (y - horizonY) * 0.1 + 2) {
            ctx.moveTo(0, y);
            ctx.lineTo(w, y);
        }
        ctx.stroke();
        ctx.restore();
    }

    private drawStaticStars(ctx: CanvasRenderingContext2D, w: number, h: number, count: number) {
        ctx.fillStyle = '#fff';
        const seed = 123;
        for(let i=0; i<count; i++) {
            const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
            const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.7;
            const size = Math.random() * 1.8;
            const alpha = Math.random() * 0.6 + 0.2;
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1.0;
    }

    private drawStaticSkyRiver(ctx: CanvasRenderingContext2D, w: number, h: number) {
        ctx.save();
        const grad = ctx.createLinearGradient(0, 0, w, h * 0.8);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.3, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(0.5, 'rgba(124, 58, 237, 0.25)');
        grad.addColorStop(0.7, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(0, h*0.2);
        ctx.quadraticCurveTo(w*0.5, h*0.5, w, h*0.4);
        ctx.lineTo(w, h*0.7);
        ctx.quadraticCurveTo(w*0.5, h*0.8, 0, h*0.5);
        ctx.fill();

        this.drawStaticStars(ctx, w, h, 200);
        ctx.restore();
    }

    private drawStaticMountains(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, h * 0.6 + yOffset);
            for(let x=0; x<=w; x+=20) {
                const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                ctx.lineTo(x, h * 0.6 + yOffset + n);
            }
            ctx.lineTo(w, h * 0.6 + yOffset);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.3;
        drawLayer(0, colorFar, 60, 0);

        ctx.globalAlpha = 0.5;
        drawLayer(60, colorNear, 40, 100);
        ctx.globalAlpha = 1.0;
    }

    private drawStaticDunes(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawDune = (yBase: number, color: string, amp: number, freq: number, offset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, yBase);
            for(let x=0; x<=w; x+=30) {
                const y = yBase + Math.sin(x * freq + offset) * amp;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, yBase);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.4;
        drawDune(h * 0.65, colorFar, 30, 0.005, 0);

        ctx.globalAlpha = 0.6;
        drawDune(h * 0.75, colorNear, 40, 0.003, 2);
        ctx.globalAlpha = 1.0;
    }

    // --- DYNAMIC RENDERING ---

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. Drifting Particles (New Layer)
        // Draw some random floating specks
        ctx.fillStyle = scene.ambientColor;
        const speckCount = 50;
        for(let i=0; i<speckCount; i++) {
            const speed = (i % 5 + 1) * 10;
            const y = (h + (i * 53) - (t * speed)) % h;
            const x = (w + (i * 97) + Math.sin(t + i)*50) % w;
            const size = Math.sin(t * 2 + i) + 2;

            ctx.globalAlpha = (Math.sin(t + i) * 0.5 + 0.5) * 0.6;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }

        // 2. Horizon Glow
        const glowH = h * 0.7;
        const pulse = 1.0 + Math.sin(t * 0.5) * 0.1;
        const horizonGrad = ctx.createRadialGradient(w/2, glowH, w * 0.2, w/2, glowH, w * 0.8 * pulse);
        horizonGrad.addColorStop(0, scene.horizon);
        horizonGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = horizonGrad;
        ctx.fillRect(0, h/2, w, h/2);

        // 3. Features
        if (scene.bgFeature === 'AURORA') {
            this.drawAurora(ctx, w, h, t);
        } else if (scene.bgFeature === 'CANOPY') {
            this.drawCanopyRays(ctx, w, h, t);
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            this.drawHeatHaze(ctx, w, h, t, scene.horizon);
        }

        // 4. Fog
        this.drawFogLayers(ctx, w, h, scene.fogColor, mapConfig, t);

        ctx.restore();
    }

    private drawAurora(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const numBands = 3;
        const baseH = h * 0.4;

        for (let i = 0; i < numBands; i++) {
            const speed = t * 0.2 + i;
            ctx.beginPath();
            ctx.moveTo(0, baseH);
            for (let x = 0; x <= w; x += 50) {
                const y = baseH + Math.sin(x * 0.005 + speed) * 50 + Math.sin(x * 0.02 - speed) * 20;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, 0);
            ctx.lineTo(0, 0);

            const grad = ctx.createLinearGradient(0, 0, w, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, `hsla(170, 80%, 60%, 0.15)`); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.fill();
        }
    }

    private drawCanopyRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'overlay';
        const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)');

        const numRays = 4;
        for (let i = 0; i < numRays; i++) {
            const angle = Math.sin(t * 0.2 + i) * 0.1 + 0.6;
            const x = w * (0.2 + i * 0.2) + Math.sin(t * 0.1) * 50;

            ctx.save();
            ctx.translate(x, -100);
            ctx.rotate(angle);
            ctx.globalAlpha = 0.15 + Math.sin(t * 0.5 + i) * 0.05;
            ctx.drawImage(raySprite, -50, 0, 100, h * 1.5);
            ctx.restore();
        }
    }

    private drawHeatHaze(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'screen';
        const grad = ctx.createLinearGradient(0, h, 0, h * 0.6);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.globalAlpha = 0.2 + Math.sin(t * 2) * 0.05;
        ctx.fillStyle = grad;
        ctx.fillRect(0, h * 0.6, w, h * 0.4);

        ctx.globalAlpha = 0.05;
        ctx.fillStyle = '#fff';
        const bands = 5;
        for(let i=0; i<bands; i++) {
            const y = h - ((t * 50 + i * 100) % (h*0.4));
            ctx.fillRect(0, y, w, 10);
        }
    }

    private drawFogLayers(ctx: CanvasRenderingContext2D, w: number, h: number, color: string, mapConfig: MapConfig, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 4;

        for (let i = 0; i < numClouds; i++) {
            const speed = 25;
            const x = ((t * speed + i * (w / numClouds)) % (w + 400)) - 200;
            const y = h * 0.6 + Math.sin(i + t * 0.2) * 50;
            const size = 400;

            ctx.globalAlpha = 0.08; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.5);
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    // VFX throttling map
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 0. AI Tick Update (System-wide clock for the agent)
        if (agent.aiUpdateTimer > 0) {
            agent.aiUpdateTimer -= dt;
        }

        // 1. Diminishing Returns (DR) Decay
        for (const type in agent.drTimers) {
            if (Object.prototype.hasOwnProperty.call(agent.drTimers, type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 2. Status Timer Ticks
        if (agent.banishTimer > 0) agent.banishTimer = Math.max(0, agent.banishTimer - dt);
        if (agent.stunTimer > 0) agent.stunTimer = Math.max(0, agent.stunTimer - dt);
        if (agent.silenceTimer > 0) agent.silenceTimer = Math.max(0, agent.silenceTimer - dt);
        if (agent.rootTimer > 0) agent.rootTimer = Math.max(0, agent.rootTimer - dt);
        if (agent.fearTimer > 0) agent.fearTimer = Math.max(0, agent.fearTimer - dt);
        if (agent.blindTimer > 0) agent.blindTimer = Math.max(0, agent.blindTimer - dt);
        if (agent.tauntTimer > 0) {
            agent.tauntTimer = Math.max(0, agent.tauntTimer - dt);
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 3. State Resolution & Priority Logic
        if (agent.banishTimer > 0) {
            agent.banished = true;
            agent.isMoving = false;
            agent.path = [];
            this.processStatusVFX(agent, dt, engine); // Early VFX process for banished
            return; 
        } else {
            if (agent.banished) {
                agent.banished = false;
                agent.visualStatus = 'NONE';
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            }
        }

        if (agent.stunTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
            agent.setAnim(AnimState.STUN);
        } else if (agent.visualStatus === 'FROZEN') {
            agent.visualStatus = 'NONE';
        }

        if (agent.fearTimer > 0) {
            // FIX: Fear Logic Jitter
            // 只有在完全停止時 (Idle) 才尋找新路徑，且強制執行完整移動
            if (agent.rootTimer <= 0) {
                // 如果正在移動，不要打斷，讓它跑完
                if (!agent.isMoving) {
                    // 擴大搜索半徑至 3-4 格，模擬長距離驚慌亂跑
                    const range = 4;
                    const center = { q: agent.q, r: agent.r };
                    const candidates = HexUtils.range(center, range).filter(h => {
                        // 排除近身 (Range < 2)，強迫跑遠
                        if (HexUtils.dist(center, h) < 2) return false;
                        return engine.map.isValid(h.q, h.r) && !engine.map.isBlocked(h.q, h.r, engine, agent.id);
                    });

                    if (candidates.length > 0) {
                        // 隨機選一個
                        const targetHex = candidates[Math.floor(Math.random() * candidates.length)];
                        // 強制走到該點，速度 1.5x
                        engine.moveAgentToHex(agent, targetHex, 0, 1.5); 
                    }
                }
            } else {
                // 如果被定身，停止移動
                agent.isMoving = false;
                agent.path = [];
            }
        }

        if (agent.rootTimer > 0) {
            agent.isMoving = false;
            agent.path = [];
        }

        if (!agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0 && agent.hp > 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }

        // 5. Visual Effects Tick (Loop for all states)
        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                // Standard Body Center height offset
                const pz = agent.physics.z + 45;
                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + pz
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('STUN', agent.stunTimer > 0);
        checkVFX('SILENCE', agent.silenceTimer > 0);
        checkVFX('FEAR', agent.fearTimer > 0);
        checkVFX('ROOT', agent.rootTimer > 0);
    }
}

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 30; 
const EXPANSION_BIAS = 0.6; // 數學膨脹量 (px)，解決縫隙

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 1. 物理座標取整
        const drawX = Math.floor(x);

        // 2. 呼吸戰場算法 (Biome Selective)
        // 草原、沙漠、冰原應該是穩固的地面，只有虛空或不穩定的地核才會懸浮
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';

        let floatOffset = 0;
        if (isFloatingBiome) {
            // 使用座標 (x, y) 作為種子，創造具有空間連續性的波動
            floatOffset = Math.sin(globalTime * 1.5 + (x * 0.01) + (y * 0.01)) * 4;
        }

        // 3. 視覺頂面 Y 軸 (相對於 drawY)
        const visualTopY = -Math.floor(height) + floatOffset;
        const drawY = Math.floor(y);

        // 膨脹幾何半徑
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        // 4. 繪製基座與側牆 (Pedestal & Walls)
        const drawFace = (idx1: number, idx2: number, color: string, isLightSide: boolean) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            // 漸層側牆 (增加立體感)
            const grad = ctx.createLinearGradient(0, visualTopY, 0, PEDESTAL_DEPTH);
            grad.addColorStop(0, color);
            grad.addColorStop(1, isLightSide ? theme.sideDark : '#020617'); // 底部漸黑，融入背景

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY); // Top-Left
            ctx.lineTo(v2.x, v2.y + visualTopY); // Top-Right
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH); // Bottom-Right (Deep)
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH); // Bottom-Left (Deep)
            ctx.closePath();
            ctx.fill();

            // 側邊高光稜線 (Rim Light)
            ctx.strokeStyle = 'rgba(255,255,255,0.08)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH);
            ctx.stroke();

            // 頂部接縫高光
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + visualTopY);
            ctx.strokeStyle = 'rgba(255,255,255,0.15)';
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            drawFace(1, 0, theme.sideDark, false);  // Right-Bottom
            drawFace(2, 1, theme.sideLight, true); // Bottom (Lightest)
            drawFace(3, 2, theme.sideDark, false);  // Left-Bottom
        } else {
            drawFace(1, 0, theme.sideDark, false);  // Right Side
            drawFace(2, 1, theme.sideLight, true); // Left Side
        }

        // 5. 繪製頂部 (Top Cap)
        ctx.translate(0, visualTopY);

        // 頂面材質光澤
        const topGrad = ctx.createLinearGradient(-r, -r, r, r);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5; // 加粗一點
        ctx.globalAlpha = 0.6;
        ctx.stroke();

        // 6. 特殊地表 (岩漿流動)
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0, layout);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // Biome Check for details too
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';
        const globalTime = Date.now() / 1000; 

        let floatOffset = 0;
        if (isFloatingBiome) {
            floatOffset = Math.sin(globalTime * 1.5 + (baseX * 0.01) + (baseY * 0.01)) * 4;
        }

        const visualY = Math.floor(baseY) - Math.floor(height) + floatOffset;

        if (type === 'FOREST' || type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { VFXFactory } from "../VFXFactory";
import { HexGeometry } from "../utils/HexGeometry";
import { HexLayout } from "../../../types";

export const SurfacePainter = {

    // Performance Optimized Liquid Renderer
    // Removed expensive per-vertex noise loop. Uses transform manipulation instead.
    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number,
        layout: HexLayout = 'FLAT' // Added layout param support
    ) {
        ctx.save();

        // 1. Base Layer (Fast Hex)
        // Instead of calculating a wobbly path, we draw a slightly smaller hex
        // and fill it with the liquid color.
        const r = HEX_SIZE * 0.9;

        // Pre-calculated hex path is faster than looped sin/cos
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);

        ctx.fillStyle = color;
        ctx.globalAlpha = 0.9 * intensity;
        ctx.fill();

        // 2. Flow Effect (Texture/Gradient Shift)
        // We use clip() to keep the effect inside the hex, then just translate a simple shape
        ctx.clip(); 

        const flowX = Math.sin(time * 0.5) * 8;
        const flowY = Math.cos(time * 0.4) * 8;

        // Darker "Crust" patches
        ctx.globalCompositeOperation = 'multiply';
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath();
        // Simple ellipse moving around
        ctx.ellipse(flowX, flowY, r * 0.6, r * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();

        // Lighter "Hot" patches
        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.3;

        const bubbleX = Math.cos(time * 0.8) * (r * 0.4);
        const bubbleY = Math.sin(time * 0.9) * (r * 0.4) * ISO_SCALE_Y;

        ctx.beginPath(); 
        ctx.arc(bubbleX, bubbleY, r * 0.3, 0, Math.PI * 2); 
        ctx.fill();

        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.12; 

        const puffs = 4;
        const twoPi = Math.PI * 2;

        for(let i=0; i<puffs; i++) {
            const angle = time * 0.15 + (i * twoPi / puffs);
            const dist = 15 + Math.sin(time * 0.8 + i) * 8;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;

            const pulse = 1.0 + Math.sin(time * 1.2 + i) * 0.15;
            const pSize = size * 0.55 * pulse;

            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }

        ctx.globalAlpha = 0.18;
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.4; 

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;

        ctx.rotate((x * 0.001) + (y * 0.001)); 

        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawDetailTexture(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        type: string,
        color: string,
        seed: number
    ) {
        const variant = Math.abs(Math.floor(seed * 100));
        const texture = VFXFactory.getTerrainDetail(type, color, variant);
        const size = texture.width;

        ctx.drawImage(texture, x - size/2, y - size/2);
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { VFXFactory } from "../VFXFactory";
import { HexGeometry } from "../utils/HexGeometry";
import { HexLayout } from "../../../types";

export const SurfacePainter = {

    // Performance Optimized Liquid Renderer
    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number,
        layout: HexLayout = 'FLAT' 
    ) {
        ctx.save();
        const r = HEX_SIZE * 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.9 * intensity;
        ctx.fill();

        ctx.clip(); 

        const flowX = Math.sin(time * 0.5) * 8;
        const flowY = Math.cos(time * 0.4) * 8;

        ctx.globalCompositeOperation = 'multiply';
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath();
        ctx.ellipse(flowX, flowY, r * 0.6, r * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.3;

        const bubbleX = Math.cos(time * 0.8) * (r * 0.4);
        const bubbleY = Math.sin(time * 0.9) * (r * 0.4) * ISO_SCALE_Y;

        ctx.beginPath(); 
        ctx.arc(bubbleX, bubbleY, r * 0.3, 0, Math.PI * 2); 
        ctx.fill();

        ctx.restore();
    },

    // --- BIOME SPECIFIC PAINTERS ---

    // 1. Procedural Grass (Wind Sway)
    drawGrass(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        density: number,
        time: number
    ) {
        ctx.save();
        ctx.translate(x, y);

        // Simple random seed based on position
        const seed = Math.sin(x * 0.1 + y * 0.1); 

        // Grass color variation
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';

        // Wind simulation
        const wind = Math.sin(time * 1.5 + x * 0.01) * 3;

        const count = 5 + Math.floor(Math.abs(seed) * 3);
        const r = HEX_SIZE * 0.6;

        for (let i = 0; i < count; i++) {
            // Random offset within hex
            const angle = (i / count) * Math.PI * 2 + seed;
            const dist = (Math.abs(Math.sin(angle * 3 + seed)) * 0.8) * r;
            const gx = Math.cos(angle) * dist;
            const gy = Math.sin(angle) * dist * ISO_SCALE_Y;

            // Individual blade variations
            const height = 6 + Math.abs(Math.sin(i + seed)) * 4;
            const sway = wind + Math.sin(time * 3 + i) * 1;

            ctx.beginPath();
            ctx.moveTo(gx, gy);
            ctx.quadraticCurveTo(gx + sway * 0.5, gy - height * 0.5, gx + sway, gy - height);

            // Darker base, lighter tip
            ctx.globalAlpha = 0.8;
            ctx.stroke();
        }
        ctx.restore();
    },

    // 2. Ice Sheen (Glossy Reflection)
    drawIceSheen(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        time: number,
        layout: HexLayout = 'FLAT'
    ) {
        ctx.save();
        ctx.translate(x, y);

        // Mask to Hex
        HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
        ctx.clip();

        // Moving light band
        const slide = (time * 0.5) % 2.5 - 0.7; // -0.7 to 1.8 range
        const w = size * 2;

        // Diagonal gradient
        const grad = ctx.createLinearGradient(-w, -w, w, w);
        const start = slide - 0.3;
        const end = slide + 0.3;

        grad.addColorStop(Math.max(0, start), 'rgba(255,255,255,0)');
        grad.addColorStop(Math.max(0, Math.min(1, slide)), 'rgba(255,255,255,0.25)'); // Specular highlight
        grad.addColorStop(Math.min(1, end), 'rgba(255,255,255,0)');

        ctx.fillStyle = grad;
        ctx.fillRect(-size, -size, size*2, size*2);

        // Static scratch marks/cracks
        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-5, 5); ctx.lineTo(5, -5);
        ctx.moveTo(2, 8); ctx.lineTo(8, 4);
        ctx.stroke();

        ctx.restore();
    },

    // 3. Sand Ripples (Dunes)
    drawSandRipples(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.15; // Very subtle

        const seed = Math.sin(x * 0.05 + y * 0.05);
        const offset = seed * 5;

        // Draw 3 wavy lines
        for(let i=-1; i<=1; i++) {
            const ly = i * 8 + offset;
            ctx.beginPath();
            for(let lx=-15; lx<=15; lx+=5) {
                const wave = Math.sin(lx * 0.3 + offset) * 2;
                if(lx === -15) ctx.moveTo(lx, ly + wave);
                else ctx.lineTo(lx, ly + wave);
            }
            ctx.stroke();
        }
        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.12; 

        const puffs = 4;
        const twoPi = Math.PI * 2;

        for(let i=0; i<puffs; i++) {
            const angle = time * 0.15 + (i * twoPi / puffs);
            const dist = 15 + Math.sin(time * 0.8 + i) * 8;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;

            const pulse = 1.0 + Math.sin(time * 1.2 + i) * 0.15;
            const pSize = size * 0.55 * pulse;

            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }

        ctx.globalAlpha = 0.18;
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.4; 

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;

        ctx.rotate((x * 0.001) + (y * 0.001)); 

        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawDetailTexture(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        type: string,
        color: string,
        seed: number
    ) {
        const variant = Math.abs(Math.floor(seed * 100));
        const texture = VFXFactory.getTerrainDetail(type, color, variant);
        const size = texture.width;

        ctx.drawImage(texture, x - size/2, y - size/2);
    }
};

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 30; 
const EXPANSION_BIAS = 0.6; // 數學膨脹量 (px)，解決縫隙

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 1. 物理座標取整
        const drawX = Math.floor(x);

        // 2. 呼吸戰場算法 (Biome Selective)
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';

        let floatOffset = 0;
        if (isFloatingBiome) {
            floatOffset = Math.sin(globalTime * 1.5 + (x * 0.01) + (y * 0.01)) * 4;
        }

        // 3. 視覺頂面 Y 軸 (相對於 drawY)
        const visualTopY = -Math.floor(height) + floatOffset;
        const drawY = Math.floor(y);

        // 膨脹幾何半徑
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        // 4. 繪製基座與側牆 (Pedestal & Walls)
        const drawFace = (idx1: number, idx2: number, color: string, isLightSide: boolean) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            // 漸層側牆 (增加立體感)
            const grad = ctx.createLinearGradient(0, visualTopY, 0, PEDESTAL_DEPTH);
            grad.addColorStop(0, color);
            grad.addColorStop(1, isLightSide ? theme.sideDark : '#020617'); // 底部漸黑，融入背景

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY); // Top-Left
            ctx.lineTo(v2.x, v2.y + visualTopY); // Top-Right
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH); // Bottom-Right (Deep)
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH); // Bottom-Left (Deep)
            ctx.closePath();
            ctx.fill();

            // 側邊高光稜線 (Rim Light)
            ctx.strokeStyle = 'rgba(255,255,255,0.08)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH);
            ctx.stroke();

            // 頂部接縫高光
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + visualTopY);
            ctx.strokeStyle = 'rgba(255,255,255,0.15)';
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            drawFace(1, 0, theme.sideDark, false);  // Right-Bottom
            drawFace(2, 1, theme.sideLight, true); // Bottom (Lightest)
            drawFace(3, 2, theme.sideDark, false);  // Left-Bottom
        } else {
            drawFace(1, 0, theme.sideDark, false);  // Right Side
            drawFace(2, 1, theme.sideLight, true); // Left Side
        }

        // 5. 繪製頂部 (Top Cap)
        ctx.translate(0, visualTopY);

        // 頂面材質光澤
        const topGrad = ctx.createLinearGradient(-r, -r, r, r);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5; // 加粗一點
        ctx.globalAlpha = 0.6;
        ctx.stroke();

        // 6. 特殊地表 (岩漿流動)
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0, layout);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string, // Usually theme.detail
        q: number, r: number,
        globalTime: number = 0,
        layout: HexLayout = 'FLAT',
        theme: any // Pass full theme for access to sideDark/rim if needed
    ) {
        // Biome Check for details too
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';

        let floatOffset = 0;
        if (isFloatingBiome) {
            floatOffset = Math.sin(globalTime * 1.5 + (baseX * 0.01) + (baseY * 0.01)) * 4;
        }

        const visualY = Math.floor(baseY) - Math.floor(height) + floatOffset;

        if (type === 'FOREST') {
            // Procedural Grass
            // Use lighter green for grass blades
            SurfacePainter.drawGrass(ctx, baseX, visualY, theme.rim || detailColor, 5, globalTime);
        } else if (type === 'ICE') {
            // Specular Ice
            SurfacePainter.drawIceSheen(ctx, baseX, visualY, HEX_SIZE, globalTime, layout);
        } else if (type === 'DESERT') {
            // Sand Ripples
            SurfacePainter.drawSandRipples(ctx, baseX, visualY, HEX_SIZE, theme.sideDark || '#92400e');
        } else if (type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { SpriteManager } from "../../sprites";
import { VisualMath } from "../../math/VisualMath";

const OBSTACLE_Z_INDEX = 10;
const PROJ_LIGHT_RADIUS_SQ = 1600;

/**
 * 網格渲染提交策略 - v11.1 (SSOT Strict Compliance)
 */
export class GridRenderStrategy {

    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];
        const layout = engine.mapConfig.layout;

        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualBaseY = py + offset;

            // SSOT: Use standard projection
            const visualSurfaceY = VisualMath.getIsoVisualY(visualBaseY, h);

            if (Math.abs(offset) > 800) continue;

            // 1. 提交障礙物
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = py; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualSurfaceY; 
                op.ttype = obstacleType;
            }

            // 2. 提交地面效果 (Hazards) -> 從 Terrain 解耦，建立獨立 Op
            const hazard = engine.map.getHazardAt(q, r, engine);
            if (hazard) {
                const hOp = renderList.next();
                hOp.type = RenderOpType.HAZARD;
                hOp.y = py; 
                hOp.z = 5; // 低於單位，高於地板
                hOp.tx = px; 
                // Note: HazardPainter will apply its own Z_LAYER bias internally
                hOp.ty = visualSurfaceY; 
                hOp.oHazard = hazard;
                hOp.time = globalTime;
            }

            // 3. 提交地形與基礎 Overlays
            const zoneInfo = engine.zones.getZoneAt(q, r);
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexUtils.dist({q, r}, {q: highlightAgent.q, r: highlightAgent.r});
                if (dist <= hoveredSkill.range + bonus) { isRange = true; rangeColor = hoveredSkill.color; }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);

            // 投射物光照計算
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = py; 
            op.z = 0; 
            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { HazardPainter } from "./grid/painters/HazardPainter"; 
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { ENV_ANCHOR_X, ENV_ANCHOR_Y } from "../graphics/EnvironmentFactory";

export class RenderPipeline {
    private renderer: GameRenderer;
    private backgroundRenderer = new BackgroundRenderer();
    private tacticalRenderer = new TacticalRenderer();
    private hudRenderer = new HUDRenderer();
    private postProcessor = new PostProcessor();
    private renderList = new RenderList();
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';
    constructor(renderer: GameRenderer) { this.renderer = renderer; }
    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }
    public update(dt: number, engine: GameEngine) { this.tacticalRenderer.update(dt, engine); }
    public draw(ctx: CanvasRenderingContext2D, engine: GameEngine, camera: Camera, highlight: Agent | null, fps: number, hoveredHex: Hex | null, hoveredSkill: Skill | null, globalTime: number): void {
        const physicalWidth = ctx.canvas.width, physicalHeight = ctx.canvas.height;
        if (physicalWidth === 0 || physicalHeight === 0) return;
        const dpr = window.devicePixelRatio || 1, logicalWidth = physicalWidth / dpr, logicalHeight = physicalHeight / dpr;
        const scene = engine.currentScene, layout = engine.mapConfig.layout;

        ctx.resetTransform(); 

        // Fallback Fill: If background renderer fails, at least show a dark void, not transparency
        ctx.fillStyle = '#020617'; 
        ctx.fillRect(0, 0, physicalWidth, physicalHeight);

        ctx.scale(dpr, dpr);

        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.renderList.reset();
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);
        this.renderer.grid.submitRenderables(this.renderList, engine, hoveredHex, hoveredSkill, highlight, engine.projectiles, this.transitionT, this.transitionPhase, globalTime);
        this.renderer.vfxRenderer.submitRenderables(this.renderList, engine, this.renderer.vfx, terrainHeightFunc, engine.mapConfig, this.transitionT, this.transitionPhase, { width: logicalWidth, height: logicalHeight, camera });
        this.renderer.unit.submitRenderables(this.renderList, engine.agents, terrainHeightFunc, globalTime, highlight, engine.mapConfig);
        this.renderList.sort();
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i], snapX = Math.round(op.tx), snapY = Math.round(op.ty);
            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime, layout);
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr, globalTime, layout, op.ttheme);
                    GridOverlays.drawOverlays(ctx, snapX, snapY - op.th, op.tsize, op.oStatus, op.oDanger, op.oLightCol, op.oLightInt, op.oRange, op.oRangeCol, op.oHover, op.oHasUnit, op.tq, op.tr, op.time, undefined, layout);
                    break;
                case RenderOpType.HAZARD: 
                    if (op.oHazard) HazardPainter.draw(ctx, snapX, snapY, op.oHazard, op.time);
                    break;
                case RenderOpType.OBSTACLE:
                    ctx.drawImage(SpriteManager.getObstacleSprite(op.ttype, layout), snapX - ENV_ANCHOR_X, snapY - ENV_ANCHOR_Y);
                    break;
                case RenderOpType.UNIT:
                    if (op.agent) this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette, layout);
                    break;
                case RenderOpType.DECAL:
                    ctx.save(); ctx.translate(snapX, snapY); ctx.scale(op.dScale, op.dScale); ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(AssetManager.getBlastZone(op.dColor), -64, -32, 128, 64); ctx.restore();
                    break;
                case RenderOpType.VFX:
                    if (op.particle) { ctx.save(); ctx.translate(snapX, snapY); ParticleRenderer.drawSingleParticle(ctx, op.particle, 0, 0, op.vProgress, op.vChaos, layout); ctx.restore(); }
                    break;
                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) occludedAgents.forEach(agent => this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig));
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime, terrainHeightFunc);
        ctx.restore(); 
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);
        ctx.restore(); 
        if (engine.directorTargetId) this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        this.tacticalRenderer.drawDebug(ctx, fps);
        let blurAmount = engine.victory.isFinishing ? 1.0 - (engine.victory.victoryTimer / VICTORY_PHASE_DURATION) : (engine.victory.winningTeam !== null ? 1.0 : 0);
        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;
        if (blurAmount > 0) this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
    }
}

import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Rebuild Static Background Layer (Gradient + Stars + Mountains)
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Draw Dynamic Atmospheric Elements
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // A. Deep Background Gradient (Richer)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.4, scene.fogColor); 
        bgGrad.addColorStop(1, scene.horizon); 
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // B. Scene Specific Static Features
        if (scene.bgFeature === 'SKY_RIVER') {
            this.drawStaticSkyRiver(ctx, w, h);
        } else {
            this.drawStaticStars(ctx, w, h, 150); // More stars
        }

        // C. Distant Grid (Retro-wave floor)
        this.drawPerspectiveGrid(ctx, w, h, scene.horizon);

        // D. Mountains / Dunes
        if (scene.bgFeature === 'DUNES') {
            this.drawStaticDunes(ctx, w, h, scene.horizon, scene.fogColor);
        } else {
            this.drawStaticMountains(ctx, w, h, scene.horizon, scene.fogColor);
        }

        // E. Vignette
        const rad = Math.max(w, h);
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad * 0.9);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,0,0,0.8)'); // Darker vignette
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawPerspectiveGrid(ctx: CanvasRenderingContext2D, w: number, h: number, color: string) {
        ctx.save();
        ctx.globalAlpha = 0.1;
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;

        const horizonY = h * 0.6;
        const centerX = w * 0.5;

        // Vertical lines converging to horizon
        ctx.beginPath();
        for (let x = -w; x < w * 2; x += 100) {
            ctx.moveTo(x, h);
            ctx.lineTo(centerX + (x - centerX) * 0.1, horizonY);
        }
        ctx.stroke();

        // Horizontal lines
        ctx.beginPath();
        for (let y = h; y > horizonY; y -= (y - horizonY) * 0.1 + 2) {
            ctx.moveTo(0, y);
            ctx.lineTo(w, y);
        }
        ctx.stroke();
        ctx.restore();
    }

    private drawStaticStars(ctx: CanvasRenderingContext2D, w: number, h: number, count: number) {
        ctx.fillStyle = '#fff';
        const seed = 123;
        for(let i=0; i<count; i++) {
            const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
            const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.7;
            const size = Math.random() * 1.8;
            const alpha = Math.random() * 0.6 + 0.2;
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1.0;
    }

    private drawStaticSkyRiver(ctx: CanvasRenderingContext2D, w: number, h: number) {
        ctx.save();
        const grad = ctx.createLinearGradient(0, 0, w, h * 0.8);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.3, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(0.5, 'rgba(124, 58, 237, 0.25)');
        grad.addColorStop(0.7, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(0, h*0.2);
        ctx.quadraticCurveTo(w*0.5, h*0.5, w, h*0.4);
        ctx.lineTo(w, h*0.7);
        ctx.quadraticCurveTo(w*0.5, h*0.8, 0, h*0.5);
        ctx.fill();

        this.drawStaticStars(ctx, w, h, 200);
        ctx.restore();
    }

    private drawStaticMountains(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, h * 0.6 + yOffset);
            for(let x=0; x<=w; x+=20) {
                const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                ctx.lineTo(x, h * 0.6 + yOffset + n);
            }
            ctx.lineTo(w, h * 0.6 + yOffset);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.3;
        drawLayer(0, colorFar, 60, 0);

        ctx.globalAlpha = 0.5;
        drawLayer(60, colorNear, 40, 100);
        ctx.globalAlpha = 1.0;
    }

    private drawStaticDunes(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawDune = (yBase: number, color: string, amp: number, freq: number, offset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, yBase);
            for(let x=0; x<=w; x+=30) {
                const y = yBase + Math.sin(x * freq + offset) * amp;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, yBase);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.4;
        drawDune(h * 0.65, colorFar, 30, 0.005, 0);

        ctx.globalAlpha = 0.6;
        drawDune(h * 0.75, colorNear, 40, 0.003, 2);
        ctx.globalAlpha = 1.0;
    }

    // --- DYNAMIC RENDERING ---

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. Drifting Particles (New Layer)
        // Draw some random floating specks
        ctx.fillStyle = scene.ambientColor;
        const speckCount = 50;
        for(let i=0; i<speckCount; i++) {
            const speed = (i % 5 + 1) * 10;
            const y = (h + (i * 53) - (t * speed)) % h;
            const x = (w + (i * 97) + Math.sin(t + i)*50) % w;
            const size = Math.sin(t * 2 + i) + 2;

            ctx.globalAlpha = (Math.sin(t + i) * 0.5 + 0.5) * 0.6;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }

        // 2. Horizon Glow
        const glowH = h * 0.7;
        const pulse = 1.0 + Math.sin(t * 0.5) * 0.1;
        const horizonGrad = ctx.createRadialGradient(w/2, glowH, w * 0.2, w/2, glowH, w * 0.8 * pulse);
        horizonGrad.addColorStop(0, scene.horizon);
        horizonGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = horizonGrad;
        ctx.fillRect(0, h/2, w, h/2);

        // 3. Features
        if (scene.bgFeature === 'AURORA') {
            this.drawAurora(ctx, w, h, t);
        } else if (scene.bgFeature === 'CANOPY') {
            this.drawCanopyRays(ctx, w, h, t);
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            this.drawHeatHaze(ctx, w, h, t, scene.horizon);
        }

        // 4. Fog / Atmospheric Effects
        if (scene.textureType === 'DESERT') {
            this.drawSandStorm(ctx, w, h, t, scene.fogColor);
        } else {
            this.drawFogLayers(ctx, w, h, scene.fogColor, mapConfig, t);
        }

        ctx.restore();
    }

    private drawAurora(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const numBands = 3;
        const baseH = h * 0.4;

        for (let i = 0; i < numBands; i++) {
            const speed = t * 0.2 + i;
            ctx.beginPath();
            ctx.moveTo(0, baseH);
            for (let x = 0; x <= w; x += 50) {
                const y = baseH + Math.sin(x * 0.005 + speed) * 50 + Math.sin(x * 0.02 - speed) * 20;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, 0);
            ctx.lineTo(0, 0);

            const grad = ctx.createLinearGradient(0, 0, w, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, `hsla(170, 80%, 60%, 0.15)`); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.fill();
        }
    }

    private drawCanopyRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'overlay';
        const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)');

        const numRays = 4;
        for (let i = 0; i < numRays; i++) {
            const angle = Math.sin(t * 0.2 + i) * 0.1 + 0.6;
            const x = w * (0.2 + i * 0.2) + Math.sin(t * 0.1) * 50;

            ctx.save();
            ctx.translate(x, -100);
            ctx.rotate(angle);
            ctx.globalAlpha = 0.15 + Math.sin(t * 0.5 + i) * 0.05;
            ctx.drawImage(raySprite, -50, 0, 100, h * 1.5);
            ctx.restore();
        }
    }

    private drawHeatHaze(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'screen';
        const grad = ctx.createLinearGradient(0, h, 0, h * 0.6);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.globalAlpha = 0.2 + Math.sin(t * 2) * 0.05;
        ctx.fillStyle = grad;
        ctx.fillRect(0, h * 0.6, w, h * 0.4);

        ctx.globalAlpha = 0.05;
        ctx.fillStyle = '#fff';
        const bands = 5;
        for(let i=0; i<bands; i++) {
            const y = h - ((t * 50 + i * 100) % (h*0.4));
            ctx.fillRect(0, y, w, 10);
        }
    }

    private drawFogLayers(ctx: CanvasRenderingContext2D, w: number, h: number, color: string, mapConfig: MapConfig, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 4;

        for (let i = 0; i < numClouds; i++) {
            const speed = 25;
            const x = ((t * speed + i * (w / numClouds)) % (w + 400)) - 200;
            const y = h * 0.6 + Math.sin(i + t * 0.2) * 50;
            const size = 400;

            ctx.globalAlpha = 0.08; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.5);
        }
    }

    private drawSandStorm(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'overlay'; // Dust accumulates

        // Simulating horizontal wind
        const windSpeed = 200;
        const drift = t * windSpeed;

        // 1. Base Dust Haze
        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.15;
        ctx.fillRect(0, 0, w, h);

        // 2. Flying Sand Clouds
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 6;
        for (let i = 0; i < numClouds; i++) {
            const x = ((drift + i * (w / numClouds)) % (w + 600)) - 300;
            const y = (Math.sin(i * 132 + t) * 0.5 + 0.5) * h;
            const size = 500;

            ctx.globalAlpha = 0.1;
            // Stretch horizontally for wind effect
            ctx.drawImage(fogSprite, x, y, size, size * 0.3);
        }

        // 3. Fast Streaks
        ctx.strokeStyle = '#fff';
        ctx.globalAlpha = 0.05;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let i = 0; i < 20; i++) {
            const streakX = ((drift * 2 + i * 153) % w);
            const streakY = (Math.sin(i * 21) * 0.5 + 0.5) * h;
            ctx.moveTo(streakX, streakY);
            ctx.lineTo(streakX + 100, streakY + 5);
        }
        ctx.stroke();
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { VFXFactory } from "../VFXFactory";
import { HexGeometry } from "../utils/HexGeometry";
import { HexLayout } from "../../../types";

export const SurfacePainter = {

    // Performance Optimized Liquid Renderer
    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number,
        layout: HexLayout = 'FLAT' 
    ) {
        ctx.save();
        const r = HEX_SIZE * 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.9 * intensity;
        ctx.fill();

        ctx.clip(); 

        const flowX = Math.sin(time * 0.5) * 8;
        const flowY = Math.cos(time * 0.4) * 8;

        ctx.globalCompositeOperation = 'multiply';
        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath();
        ctx.ellipse(flowX, flowY, r * 0.6, r * 0.4, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.3;

        const bubbleX = Math.cos(time * 0.8) * (r * 0.4);
        const bubbleY = Math.sin(time * 0.9) * (r * 0.4) * ISO_SCALE_Y;

        ctx.beginPath(); 
        ctx.arc(bubbleX, bubbleY, r * 0.3, 0, Math.PI * 2); 
        ctx.fill();

        ctx.restore();
    },

    // --- BIOME SPECIFIC PAINTERS ---

    // 1. Procedural Grass (Wind Sway)
    drawGrass(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        density: number,
        time: number
    ) {
        ctx.save();
        ctx.translate(x, y);

        // Simple random seed based on position
        const seed = Math.sin(x * 0.1 + y * 0.1); 

        // Grass color variation
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';

        // Wind simulation
        const wind = Math.sin(time * 1.5 + x * 0.01) * 3;

        const count = 5 + Math.floor(Math.abs(seed) * 3);
        const r = HEX_SIZE * 0.6;

        for (let i = 0; i < count; i++) {
            // Random offset within hex
            const angle = (i / count) * Math.PI * 2 + seed;
            const dist = (Math.abs(Math.sin(angle * 3 + seed)) * 0.8) * r;
            const gx = Math.cos(angle) * dist;
            const gy = Math.sin(angle) * dist * ISO_SCALE_Y;

            // Individual blade variations
            const height = 6 + Math.abs(Math.sin(i + seed)) * 4;
            const sway = wind + Math.sin(time * 3 + i) * 1;

            ctx.beginPath();
            ctx.moveTo(gx, gy);
            ctx.quadraticCurveTo(gx + sway * 0.5, gy - height * 0.5, gx + sway, gy - height);

            // Darker base, lighter tip
            ctx.globalAlpha = 0.8;
            ctx.stroke();
        }
        ctx.restore();
    },

    // 2. Ice Sheen (Glossy Reflection)
    drawIceSheen(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        time: number,
        layout: HexLayout = 'FLAT'
    ) {
        ctx.save();
        ctx.translate(x, y);

        // Mask to Hex
        HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true, layout);
        ctx.clip();

        // Moving light band
        const slide = (time * 0.5) % 2.5 - 0.7; // -0.7 to 1.8 range
        const w = size * 2;

        // Diagonal gradient
        const grad = ctx.createLinearGradient(-w, -w, w, w);
        const start = slide - 0.3;
        const end = slide + 0.3;

        // FIX: Clamp all gradient stops to [0, 1] range to prevent IndexSizeError
        grad.addColorStop(Math.max(0, Math.min(1, start)), 'rgba(255,255,255,0)');
        grad.addColorStop(Math.max(0, Math.min(1, slide)), 'rgba(255,255,255,0.25)'); // Specular highlight
        grad.addColorStop(Math.max(0, Math.min(1, end)), 'rgba(255,255,255,0)');

        ctx.fillStyle = grad;
        ctx.fillRect(-size, -size, size*2, size*2);

        // Static scratch marks/cracks
        ctx.strokeStyle = 'rgba(255,255,255,0.1)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-5, 5); ctx.lineTo(5, -5);
        ctx.moveTo(2, 8); ctx.lineTo(8, 4);
        ctx.stroke();

        ctx.restore();
    },

    // 3. Sand Ripples (Dunes)
    drawSandRipples(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.15; // Very subtle

        const seed = Math.sin(x * 0.05 + y * 0.05);
        const offset = seed * 5;

        // Draw 3 wavy lines
        for(let i=-1; i<=1; i++) {
            const ly = i * 8 + offset;
            ctx.beginPath();
            for(let lx=-15; lx<=15; lx+=5) {
                const wave = Math.sin(lx * 0.3 + offset) * 2;
                if(lx === -15) ctx.moveTo(lx, ly + wave);
                else ctx.lineTo(lx, ly + wave);
            }
            ctx.stroke();
        }
        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.12; 

        const puffs = 4;
        const twoPi = Math.PI * 2;

        for(let i=0; i<puffs; i++) {
            const angle = time * 0.15 + (i * twoPi / puffs);
            const dist = 15 + Math.sin(time * 0.8 + i) * 8;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;

            const pulse = 1.0 + Math.sin(time * 1.2 + i) * 0.15;
            const pSize = size * 0.55 * pulse;

            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }

        ctx.globalAlpha = 0.18;
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.4; 

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;

        ctx.rotate((x * 0.001) + (y * 0.001)); 

        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawDetailTexture(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        type: string,
        color: string,
        seed: number
    ) {
        const variant = Math.abs(Math.floor(seed * 100));
        const texture = VFXFactory.getTerrainDetail(type, color, variant);
        const size = texture.width;

        ctx.drawImage(texture, x - size/2, y - size/2);
    }
};

