import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Rebuild Static Background Layer (Gradient + Stars + Mountains)
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Draw Dynamic Atmospheric Elements
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private hexToRgba(hex: string, alpha: number): string {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        return `rgba(${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}, ${alpha})`;
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // A. Deep Background Gradient (Richer)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.4, scene.fogColor); 
        bgGrad.addColorStop(1, scene.horizon); 
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // B. Scene Specific Static Features
        if (scene.bgFeature === 'SKY_RIVER') {
            this.drawStaticSkyRiver(ctx, w, h);
        } else {
            this.drawStaticStars(ctx, w, h, 150); // More stars
        }

        // C. Distant Grid (Retro-wave floor)
        // Draw grid BEFORE horizon seam so seam covers it
        this.drawPerspectiveGrid(ctx, w, h, scene.horizon);

        // D. Mountains / Dunes
        if (scene.bgFeature === 'DUNES') {
            this.drawStaticDunes(ctx, w, h, scene.horizon, scene.fogColor);
        } else {
            this.drawStaticMountains(ctx, w, h, scene.horizon, scene.fogColor);
        }

        // E. Horizon Blending Strip (Seam Fix) - Improved Gradient
        // Increased Height to 350 to allow smoother falloff
        const horizonY = h * 0.6;
        const seamHeight = 350; 
        const seamGrad = ctx.createLinearGradient(0, horizonY - seamHeight * 0.6, 0, horizonY + seamHeight * 0.4);

        const fogRgbaFull = this.hexToRgba(scene.fogColor, 1.0); // Full opacity at core
        const fogRgbaZero = this.hexToRgba(scene.fogColor, 0);

        seamGrad.addColorStop(0, fogRgbaZero);
        seamGrad.addColorStop(0.4, fogRgbaFull); 
        seamGrad.addColorStop(0.6, fogRgbaFull); 
        seamGrad.addColorStop(1, fogRgbaZero);

        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = seamGrad;
        ctx.fillRect(0, horizonY - seamHeight * 0.6, w, seamHeight);

        // F. Vignette
        const rad = Math.max(w, h);
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad * 0.9);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,0,0,0.8)'); // Darker vignette
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawPerspectiveGrid(ctx: CanvasRenderingContext2D, w: number, h: number, color: string) {
        ctx.save();
        ctx.globalAlpha = 0.15; // Slightly clearer
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;

        const horizonY = h * 0.6;
        const centerX = w * 0.5;

        // Vertical lines converging to horizon
        ctx.beginPath();
        for (let x = -w; x < w * 2; x += 100) {
            ctx.moveTo(x, h);
            ctx.lineTo(centerX + (x - centerX) * 0.1, horizonY);
        }
        ctx.stroke();

        // Horizontal lines - With Fadeout near horizon
        for (let y = h; y > horizonY; y -= (y - horizonY) * 0.1 + 2) {
            // Distance Factor (0 at horizon, 1 at bottom)
            const dist = (y - horizonY) / (h - horizonY);
            // Only draw if not too close to horizon to avoid moire/aliasing
            if (dist < 0.05) continue; 

            ctx.globalAlpha = 0.15 * Math.pow(dist, 0.5); // Fade out as it goes back
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(w, y);
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawStaticStars(ctx: CanvasRenderingContext2D, w: number, h: number, count: number) {
        ctx.fillStyle = '#fff';
        const seed = 123;
        for(let i=0; i<count; i++) {
            const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
            const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.7;
            const size = Math.random() * 1.8;
            const alpha = Math.random() * 0.6 + 0.2;
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1.0;
    }

    private drawStaticSkyRiver(ctx: CanvasRenderingContext2D, w: number, h: number) {
        ctx.save();
        const grad = ctx.createLinearGradient(0, 0, w, h * 0.8);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.3, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(0.5, 'rgba(124, 58, 237, 0.25)');
        grad.addColorStop(0.7, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(0, h*0.2);
        ctx.quadraticCurveTo(w*0.5, h*0.5, w, h*0.4);
        ctx.lineTo(w, h*0.7);
        ctx.quadraticCurveTo(w*0.5, h*0.8, 0, h*0.5);
        ctx.fill();

        this.drawStaticStars(ctx, w, h, 200);
        ctx.restore();
    }

    private drawStaticMountains(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, h * 0.6 + yOffset);
            for(let x=0; x<=w; x+=20) {
                const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                ctx.lineTo(x, h * 0.6 + yOffset + n);
            }
            ctx.lineTo(w, h * 0.6 + yOffset);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.3;
        drawLayer(0, colorFar, 60, 0);

        ctx.globalAlpha = 0.5;
        drawLayer(60, colorNear, 40, 100);
        ctx.globalAlpha = 1.0;
    }

    private drawStaticDunes(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawDune = (yBase: number, color: string, amp: number, freq: number, offset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, yBase);
            for(let x=0; x<=w; x+=30) {
                const y = yBase + Math.sin(x * freq + offset) * amp;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, yBase);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.4;
        drawDune(h * 0.65, colorFar, 30, 0.005, 0);

        ctx.globalAlpha = 0.6;
        drawDune(h * 0.75, colorNear, 40, 0.003, 2);
        ctx.globalAlpha = 1.0;
    }

    // --- DYNAMIC RENDERING ---

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. Drifting Particles (New Layer)
        // Draw some random floating specks
        ctx.fillStyle = scene.ambientColor;
        const speckCount = 50;
        for(let i=0; i<speckCount; i++) {
            const speed = (i % 5 + 1) * 10;
            const y = (h + (i * 53) - (t * speed)) % h;
            const x = (w + (i * 97) + Math.sin(t + i)*50) % w;
            const size = Math.sin(t * 2 + i) + 2;

            ctx.globalAlpha = (Math.sin(t + i) * 0.5 + 0.5) * 0.6;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }

        // 2. Horizon Glow
        const glowH = h * 0.7;
        const pulse = 1.0 + Math.sin(t * 0.5) * 0.1;
        const horizonGrad = ctx.createRadialGradient(w/2, glowH, w * 0.2, w/2, glowH, w * 0.8 * pulse);
        horizonGrad.addColorStop(0, scene.horizon);
        horizonGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = horizonGrad;
        ctx.fillRect(0, h/2, w, h/2);

        // 3. Features
        if (scene.bgFeature === 'AURORA') {
            this.drawAurora(ctx, w, h, t);
        } else if (scene.bgFeature === 'CANOPY') {
            this.drawCanopyRays(ctx, w, h, t);
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            this.drawHeatHaze(ctx, w, h, t, scene.horizon);
        }

        // 4. Fog / Atmospheric Effects
        if (scene.textureType === 'DESERT') {
            this.drawSandStorm(ctx, w, h, t, scene.fogColor);
        } else {
            this.drawFogLayers(ctx, w, h, scene.fogColor, mapConfig, t);
        }

        ctx.restore();
    }

    private drawAurora(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const numBands = 3;
        const baseH = h * 0.4;

        for (let i = 0; i < numBands; i++) {
            const speed = t * 0.2 + i;
            ctx.beginPath();
            ctx.moveTo(0, baseH);
            for (let x = 0; x <= w; x += 50) {
                const y = baseH + Math.sin(x * 0.005 + speed) * 50 + Math.sin(x * 0.02 - speed) * 20;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, 0);
            ctx.lineTo(0, 0);

            const grad = ctx.createLinearGradient(0, 0, w, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, `hsla(170, 80%, 60%, 0.15)`); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.fill();
        }
    }

    private drawCanopyRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'overlay';
        const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)');

        const numRays = 4;
        for (let i = 0; i < numRays; i++) {
            const angle = Math.sin(t * 0.2 + i) * 0.1 + 0.6;
            const x = w * (0.2 + i * 0.2) + Math.sin(t * 0.1) * 50;

            ctx.save();
            ctx.translate(x, -100);
            ctx.rotate(angle);
            ctx.globalAlpha = 0.15 + Math.sin(t * 0.5 + i) * 0.05;
            ctx.drawImage(raySprite, -50, 0, 100, h * 1.5);
            ctx.restore();
        }
    }

    private drawHeatHaze(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'screen';
        const grad = ctx.createLinearGradient(0, h, 0, h * 0.6);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.globalAlpha = 0.2 + Math.sin(t * 2) * 0.05;
        ctx.fillStyle = grad;
        ctx.fillRect(0, h * 0.6, w, h * 0.4);

        ctx.globalAlpha = 0.05;
        ctx.fillStyle = '#fff';
        const bands = 5;
        for(let i=0; i<bands; i++) {
            const y = h - ((t * 50 + i * 100) % (h*0.4));
            ctx.fillRect(0, y, w, 10);
        }
    }

    private drawFogLayers(ctx: CanvasRenderingContext2D, w: number, h: number, color: string, mapConfig: MapConfig, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 4;

        for (let i = 0; i < numClouds; i++) {
            const speed = 25;
            const x = ((t * speed + i * (w / numClouds)) % (w + 400)) - 200;
            const y = h * 0.6 + Math.sin(i + t * 0.2) * 50;
            const size = 400;

            ctx.globalAlpha = 0.08; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.5);
        }
    }

    private drawSandStorm(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'overlay'; // Dust accumulates

        // Simulating horizontal wind
        const windSpeed = 200;
        const drift = t * windSpeed;

        // 1. Base Dust Haze
        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.15;
        ctx.fillRect(0, 0, w, h);

        // 2. Flying Sand Clouds
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 6;
        for (let i = 0; i < numClouds; i++) {
            const x = ((drift + i * (w / numClouds)) % (w + 600)) - 300;
            const y = (Math.sin(i * 132 + t) * 0.5 + 0.5) * h;
            const size = 500;

            ctx.globalAlpha = 0.1;
            // Stretch horizontally for wind effect
            ctx.drawImage(fogSprite, x, y, size, size * 0.3);
        }

        // 3. Fast Streaks
        ctx.strokeStyle = '#fff';
        ctx.globalAlpha = 0.05;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let i = 0; i < 20; i++) {
            const streakX = ((drift * 2 + i * 153) % w);
            const streakY = (Math.sin(i * 21) * 0.5 + 0.5) * h;
            ctx.moveTo(streakX, streakY);
            ctx.lineTo(streakX + 100, streakY + 5);
        }
        ctx.stroke();
    }
}

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 30; 
const EXPANSION_BIAS = 0.6; // 數學膨脹量 (px)，解決縫隙

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 1. 物理座標取整
        const drawX = Math.floor(x);

        // 2. 呼吸戰場算法 (Biome Selective)
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';

        let floatOffset = 0;
        if (isFloatingBiome) {
            floatOffset = Math.sin(globalTime * 1.5 + (x * 0.01) + (y * 0.01)) * 4;
        }

        // 3. 視覺頂面 Y 軸 (相對於 drawY)
        const visualTopY = -Math.floor(height) + floatOffset;
        const drawY = Math.floor(y);

        // 膨脹幾何半徑
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        // 4. 繪製基座與側牆 (Pedestal & Walls)
        const drawFace = (idx1: number, idx2: number, color: string, isLightSide: boolean) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            // 漸層側牆 (增加立體感)
            const grad = ctx.createLinearGradient(0, visualTopY, 0, PEDESTAL_DEPTH);
            grad.addColorStop(0, color);
            grad.addColorStop(1, isLightSide ? theme.sideDark : '#020617'); // 底部漸黑，融入背景

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY); // Top-Left
            ctx.lineTo(v2.x, v2.y + visualTopY); // Top-Right
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH); // Bottom-Right (Deep)
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH); // Bottom-Left (Deep)
            ctx.closePath();
            ctx.fill();

            // 側邊高光稜線 (Rim Light)
            ctx.strokeStyle = 'rgba(255,255,255,0.08)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH);
            ctx.stroke();

            // 頂部接縫高光
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + visualTopY);
            ctx.strokeStyle = 'rgba(255,255,255,0.15)';
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            drawFace(1, 0, theme.sideDark, false);  // Right-Bottom
            drawFace(2, 1, theme.sideLight, true); // Bottom (Lightest)
            drawFace(3, 2, theme.sideDark, false);  // Left-Bottom
        } else {
            drawFace(1, 0, theme.sideDark, false);  // Right Side
            drawFace(2, 1, theme.sideLight, true); // Left Side
        }

        // 5. 繪製頂部 (Top Cap)
        ctx.translate(0, visualTopY);

        // 頂面材質光澤
        const topGrad = ctx.createLinearGradient(-r, -r, r, r);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5; // 加粗一點
        ctx.globalAlpha = 0.6;
        ctx.stroke();

        // 6. 特殊地表 (岩漿流動)
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0, layout);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string, // Usually theme.detail
        q: number, r: number,
        globalTime: number = 0,
        layout: HexLayout = 'FLAT',
        theme: any // Pass full theme for access to sideDark/rim if needed
    ) {
        // Biome Check for details too
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';

        let floatOffset = 0;
        if (isFloatingBiome) {
            floatOffset = Math.sin(globalTime * 1.5 + (baseX * 0.01) + (baseY * 0.01)) * 4;
        }

        const visualY = Math.floor(baseY) - Math.floor(height) + floatOffset;

        if (type === 'FOREST') {
            // Procedural Grass
            // [VISUAL FIX] Use theme.sideLight (Mid-Green) instead of Rim/Detail (Bright Green)
            // This makes the grass blend better with the block's top face.
            SurfacePainter.drawGrass(ctx, baseX, visualY, theme.sideLight || '#166534', 5, globalTime);
        } else if (type === 'ICE') {
            // Specular Ice
            SurfacePainter.drawIceSheen(ctx, baseX, visualY, HEX_SIZE, globalTime, layout);
        } else if (type === 'DESERT') {
            // Sand Ripples
            SurfacePainter.drawSandRipples(ctx, baseX, visualY, HEX_SIZE, theme.sideDark || '#92400e');
        } else if (type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Rebuild Static Background Layer (Gradient + Stars + Mountains)
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Draw Dynamic Atmospheric Elements
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private hexToRgba(hex: string, alpha: number): string {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        return `rgba(${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}, ${alpha})`;
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // A. Deep Background Gradient (Richer)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.4, scene.fogColor); 
        bgGrad.addColorStop(1, scene.horizon); 
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // B. Scene Specific Static Features
        if (scene.bgFeature === 'SKY_RIVER') {
            this.drawStaticSkyRiver(ctx, w, h);
        } else {
            this.drawStaticStars(ctx, w, h, 150); // More stars
        }

        // C. Distant Grid (Retro-wave floor)
        // Draw grid BEFORE horizon seam so seam covers it
        this.drawPerspectiveGrid(ctx, w, h, scene.horizon);

        // D. Mountains / Dunes
        if (scene.bgFeature === 'DUNES') {
            this.drawStaticDunes(ctx, w, h, scene.horizon, scene.fogColor);
        } else {
            this.drawStaticMountains(ctx, w, h, scene.horizon, scene.fogColor);
        }

        // E. Horizon Blending Strip (Seam Fix) - Improved Gradient
        // Increased Height to 350 to allow smoother falloff
        const horizonY = h * 0.6;
        const seamHeight = 350; 
        const seamGrad = ctx.createLinearGradient(0, horizonY - seamHeight * 0.6, 0, horizonY + seamHeight * 0.4);

        // [FIX] Using 'screen' or brighter blend modes earlier caused the line. 
        // We use source-over with 100% opacity at the core to physically cover the seam.
        const fogRgbaFull = this.hexToRgba(scene.fogColor, 1.0); // Full opacity at core
        const fogRgbaMid = this.hexToRgba(scene.fogColor, 0.8);
        const fogRgbaZero = this.hexToRgba(scene.fogColor, 0);

        seamGrad.addColorStop(0, fogRgbaZero);
        seamGrad.addColorStop(0.3, fogRgbaMid);
        seamGrad.addColorStop(0.5, fogRgbaFull); 
        seamGrad.addColorStop(0.7, fogRgbaMid);
        seamGrad.addColorStop(1, fogRgbaZero);

        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = seamGrad;
        ctx.fillRect(0, horizonY - seamHeight * 0.6, w, seamHeight);

        // F. Vignette
        const rad = Math.max(w, h);
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad * 0.9);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,0,0,0.8)'); // Darker vignette
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawPerspectiveGrid(ctx: CanvasRenderingContext2D, w: number, h: number, color: string) {
        ctx.save();
        ctx.globalAlpha = 0.15; // Slightly clearer
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;

        const horizonY = h * 0.6;
        const centerX = w * 0.5;

        // Vertical lines converging to horizon
        ctx.beginPath();
        for (let x = -w; x < w * 2; x += 100) {
            ctx.moveTo(x, h);
            ctx.lineTo(centerX + (x - centerX) * 0.1, horizonY);
        }
        ctx.stroke();

        // Horizontal lines - With Fadeout near horizon
        // [FIX] Start fading out earlier (0.15 instead of 0.05) to avoid the line intersection artifact
        for (let y = h; y > horizonY; y -= (y - horizonY) * 0.1 + 2) {
            // Distance Factor (0 at horizon, 1 at bottom)
            const dist = (y - horizonY) / (h - horizonY);
            if (dist < 0.15) continue; 

            ctx.globalAlpha = 0.15 * Math.pow(dist, 0.5); // Fade out as it goes back
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(w, y);
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawStaticStars(ctx: CanvasRenderingContext2D, w: number, h: number, count: number) {
        ctx.fillStyle = '#fff';
        const seed = 123;
        for(let i=0; i<count; i++) {
            const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
            const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.7;
            const size = Math.random() * 1.8;
            const alpha = Math.random() * 0.6 + 0.2;
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1.0;
    }

    private drawStaticSkyRiver(ctx: CanvasRenderingContext2D, w: number, h: number) {
        ctx.save();
        const grad = ctx.createLinearGradient(0, 0, w, h * 0.8);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.3, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(0.5, 'rgba(124, 58, 237, 0.25)');
        grad.addColorStop(0.7, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(0, h*0.2);
        ctx.quadraticCurveTo(w*0.5, h*0.5, w, h*0.4);
        ctx.lineTo(w, h*0.7);
        ctx.quadraticCurveTo(w*0.5, h*0.8, 0, h*0.5);
        ctx.fill();

        this.drawStaticStars(ctx, w, h, 200);
        ctx.restore();
    }

    private drawStaticMountains(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, h * 0.6 + yOffset);
            for(let x=0; x<=w; x+=20) {
                const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                ctx.lineTo(x, h * 0.6 + yOffset + n);
            }
            ctx.lineTo(w, h * 0.6 + yOffset);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.3;
        drawLayer(0, colorFar, 60, 0);

        ctx.globalAlpha = 0.5;
        drawLayer(60, colorNear, 40, 100);
        ctx.globalAlpha = 1.0;
    }

    private drawStaticDunes(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawDune = (yBase: number, color: string, amp: number, freq: number, offset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, yBase);
            for(let x=0; x<=w; x+=30) {
                const y = yBase + Math.sin(x * freq + offset) * amp;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, yBase);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.4;
        drawDune(h * 0.65, colorFar, 30, 0.005, 0);

        ctx.globalAlpha = 0.6;
        drawDune(h * 0.75, colorNear, 40, 0.003, 2);
        ctx.globalAlpha = 1.0;
    }

    // --- DYNAMIC RENDERING ---

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. Drifting Particles (New Layer)
        // Draw some random floating specks
        ctx.fillStyle = scene.ambientColor;
        const speckCount = 50;
        for(let i=0; i<speckCount; i++) {
            const speed = (i % 5 + 1) * 10;
            const y = (h + (i * 53) - (t * speed)) % h;
            const x = (w + (i * 97) + Math.sin(t + i)*50) % w;
            const size = Math.sin(t * 2 + i) + 2;

            ctx.globalAlpha = (Math.sin(t + i) * 0.5 + 0.5) * 0.6;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }

        // 2. Horizon Glow
        const glowH = h * 0.7;
        const pulse = 1.0 + Math.sin(t * 0.5) * 0.1;
        const horizonGrad = ctx.createRadialGradient(w/2, glowH, w * 0.2, w/2, glowH, w * 0.8 * pulse);
        horizonGrad.addColorStop(0, scene.horizon);
        horizonGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = horizonGrad;
        ctx.fillRect(0, h/2, w, h/2);

        // 3. Features
        if (scene.bgFeature === 'AURORA') {
            this.drawAurora(ctx, w, h, t);
        } else if (scene.bgFeature === 'CANOPY') {
            this.drawCanopyRays(ctx, w, h, t);
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            this.drawHeatHaze(ctx, w, h, t, scene.horizon);
        }

        // 4. Fog / Atmospheric Effects
        if (scene.textureType === 'DESERT') {
            this.drawSandStorm(ctx, w, h, t, scene.fogColor);
        } else {
            this.drawFogLayers(ctx, w, h, scene.fogColor, mapConfig, t);
        }

        ctx.restore();
    }

    private drawAurora(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const numBands = 3;
        const baseH = h * 0.4;

        for (let i = 0; i < numBands; i++) {
            const speed = t * 0.2 + i;
            ctx.beginPath();
            ctx.moveTo(0, baseH);
            for (let x = 0; x <= w; x += 50) {
                const y = baseH + Math.sin(x * 0.005 + speed) * 50 + Math.sin(x * 0.02 - speed) * 20;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, 0);
            ctx.lineTo(0, 0);

            const grad = ctx.createLinearGradient(0, 0, w, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, `hsla(170, 80%, 60%, 0.15)`); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.fill();
        }
    }

    private drawCanopyRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'overlay';
        const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)');

        const numRays = 4;
        for (let i = 0; i < numRays; i++) {
            const angle = Math.sin(t * 0.2 + i) * 0.1 + 0.6;
            const x = w * (0.2 + i * 0.2) + Math.sin(t * 0.1) * 50;

            ctx.save();
            ctx.translate(x, -100);
            ctx.rotate(angle);
            ctx.globalAlpha = 0.15 + Math.sin(t * 0.5 + i) * 0.05;
            ctx.drawImage(raySprite, -50, 0, 100, h * 1.5);
            ctx.restore();
        }
    }

    private drawHeatHaze(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'screen';
        const grad = ctx.createLinearGradient(0, h, 0, h * 0.6);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.globalAlpha = 0.2 + Math.sin(t * 2) * 0.05;
        ctx.fillStyle = grad;
        ctx.fillRect(0, h * 0.6, w, h * 0.4);

        ctx.globalAlpha = 0.05;
        ctx.fillStyle = '#fff';
        const bands = 5;
        for(let i=0; i<bands; i++) {
            const y = h - ((t * 50 + i * 100) % (h*0.4));
            ctx.fillRect(0, y, w, 10);
        }
    }

    private drawFogLayers(ctx: CanvasRenderingContext2D, w: number, h: number, color: string, mapConfig: MapConfig, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 4;

        for (let i = 0; i < numClouds; i++) {
            const speed = 25;
            const x = ((t * speed + i * (w / numClouds)) % (w + 400)) - 200;
            const y = h * 0.6 + Math.sin(i + t * 0.2) * 50;
            const size = 400;

            ctx.globalAlpha = 0.08; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.5);
        }
    }

    private drawSandStorm(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'overlay'; 

        const windSpeed = 300; // Increased wind speed
        const drift = t * windSpeed;

        // 1. Base Dust Haze
        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.2; // Slightly more visible
        ctx.fillRect(0, 0, w, h);

        // 2. Flying Sand Clouds (Midground)
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 6;
        for (let i = 0; i < numClouds; i++) {
            const x = ((drift + i * (w / numClouds)) % (w + 600)) - 300;
            const y = (Math.sin(i * 132 + t) * 0.5 + 0.5) * h;
            const size = 500;

            ctx.globalAlpha = 0.12;
            ctx.drawImage(fogSprite, x, y, size, size * 0.3);
        }

        // 3. Fast Streaks (Foreground Wind) - More distinct
        ctx.strokeStyle = '#fff';
        ctx.globalAlpha = 0.08;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let i = 0; i < 30; i++) {
            // Skew streaks to look like they are flying over the grid
            const streakX = ((drift * 2.5 + i * 153) % (w + 200)) - 100;
            const streakY = (Math.sin(i * 21) * 0.5 + 0.5) * (h * 0.8) + h * 0.2; // Keep lower on screen
            ctx.moveTo(streakX, streakY);
            ctx.lineTo(streakX + 150, streakY + 5);
        }
        ctx.stroke();
    }
}

import { VFXStateManager } from "./state";

export class VFXAmbience {
    private timer: number = 0;

    public update(dt: number, type: string, state: VFXStateManager) {
        if (type === 'NONE') return;

        this.timer += dt;

        // Rate Control:
        // Snow/Ash/Sand: Frequent spawn (Dense atmosphere)
        // Others: Sparse spawn
        let rate = 0.15;
        if (type === 'SNOW' || type === 'ASH') rate = 0.03;
        if (type === 'SAND') rate = 0.015; // Even faster spawn for Sand

        if (this.timer > rate) {
            this.timer = 0;

            const p = state.getParticle();
            p.type = 'ATMOSPHERE'; 

            // Default random spawn logic (overridden for Sand)
            let x = Math.random() * 1600 - 200;
            const y = Math.random() * 1000 - 200;

            // Randomize Z for parallax feeling
            p.z = Math.random() * 400 + 50; 

            if (type === 'SNOW') {
                p.x = x; p.y = y;
                p.color = '#fff';
                p.size = Math.random() * 2.5 + 1.5;
                p.vx = 40 + Math.random() * 30; // Wind
                p.vy = 80 + Math.random() * 40; // Fall
                p.life = 4.0; p.maxLife = 4.0;
                p.blendMode = 'source-over';
            } else if (type === 'ASH') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#1c1917' : '#451a03'; // Dark Ash
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 30 + Math.random() * 20;
                p.life = 5.0; p.maxLife = 5.0;
                p.blendMode = 'source-over';
            } else if (type === 'EMBER') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#f59e0b' : '#ef4444';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 40;
                p.vy = -40 - Math.random() * 30; // Rise
                p.life = 2.5; p.maxLife = 2.5;
                p.blendMode = 'screen'; 
            } else if (type === 'SPORES') {
                p.x = x; p.y = y;
                // Mystic floaty particles
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2.5 + 0.5;
                p.vx = (Math.random() - 0.5) * 15;
                p.vy = (Math.random() - 0.5) * 15;
                p.life = 6.0; p.maxLife = 6.0;
                p.blendMode = 'screen';
            } else if (type === 'SAND') {
                // Directional High Speed Sandstorm
                // Spawn off-screen left, fly right
                p.x = -100; 
                p.y = Math.random() * 1200 - 200; // Full vertical coverage

                // Amber/Tan colors
                p.color = Math.random() > 0.6 ? '#fcd34d' : '#d97706'; 
                p.size = Math.random() * 3 + 1; // Slightly larger chunks

                // High horizontal velocity
                p.vx = 800 + Math.random() * 400; // Very Fast
                p.vy = 50 + Math.random() * 30; // Slight fall/drift

                p.life = 2.5; p.maxLife = 2.5; // Enough to cross screen
                p.blendMode = 'source-over';
            }

            state.particles.push(p);
        }
    }
}

import { OBSTACLE_STYLES, HEX_SIZE, BASE_HEIGHT, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../constants";
import { createCanvas } from "./CanvasUtils";
import { HexGeometry } from "./utils/HexGeometry"; 
import { HexLayout } from "../../types";

// --- STRICT ALIGNMENT CONSTANTS ---
export const ENV_CANVAS_W = 128;
export const ENV_CANVAS_H = 160;
export const ENV_ANCHOR_X = 64;  
export const ENV_ANCHOR_Y = 140; 

export const EnvironmentFactory = {

    generateObstacle(styleKey: string, layout: HexLayout): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);

        // Setup Anchor: (0,0) is the CENTER of the hexagonal SURFACE on the ground
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);

        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        // 1. Draw Base Shadow (Strict Hexagon Footprint)
        this.drawHexShadow(ctx, layout);

        // 2. Draw Object based on Type (Growing Upwards y < 0)
        if (styleKey === 'TREE') {
            this.drawIsoTree(ctx, style, layout);
        } else if (styleKey === 'ICE_CRYSTAL') {
            this.drawIsoCrystal(ctx, style, layout);
        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            this.drawIsoPillar(ctx, style, layout);
        } else if (styleKey === 'SANDSTONE') {
            // New Organic Rock Cluster for Desert
            this.drawIsoRockCluster(ctx, style, layout);
        } else {
            this.drawIsoWall(ctx, style, layout); // Default Wall
        }

        return canvas;
    },

    generateIceBlock(layout: HexLayout): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ENV_CANVAS_W, ENV_CANVAS_H);
        ctx.translate(ENV_ANCHOR_X, ENV_ANCHOR_Y);
        const style = OBSTACLE_STYLES['ICE_CRYSTAL'];
        this.drawIsoCrystal(ctx, style, layout, 0.7);
        return canvas;
    },

    // =========================================================================================
    // 🏗️ GEOMETRY BUILDERS (Layout Aware)
    // =========================================================================================

    drawHexShadow(ctx: CanvasRenderingContext2D, layout: HexLayout) {
        ctx.save();
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.filter = 'blur(4px)';
        const r = HEX_SIZE * 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();
        ctx.restore();
    },

    drawIsoWall(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        // Dynamic Height: Multiplier increased to 3.0 to keep walls feeling tall with small blocks
        const height = BLOCK_HEIGHT * 3.0; 
        const r = HEX_SIZE * 0.9; 
        const topY = -height;

        const verts = HexGeometry.getVertices(r, true, layout);

        // --- WALL FACES ---
        if (layout === 'FLAT') {
            // Left Face (v3 -> v2)
            this.drawQuad(ctx, verts[3], verts[2], topY, style.dark);
            this.drawEdge(ctx, verts[3], verts[2], topY, style.highlight);

            // Front Face (v2 -> v1)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.main);

            // Right Face (v1 -> v0)
            this.drawQuad(ctx, verts[1], verts[0], topY, style.light);
            this.drawEdge(ctx, verts[1], verts[0], topY, style.highlight);

        } else {
            // Left Face (v2 -> v1)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.sideDark || style.dark); 
            this.drawEdge(ctx, verts[2], verts[1], topY, style.highlight);

            // Right Face (v1 -> v0)
            this.drawQuad(ctx, verts[1], verts[0], topY, style.sideLight || style.main);
            this.drawEdge(ctx, verts[1], verts[0], topY, style.highlight);

            // Center Seam Highlight
            ctx.beginPath();
            ctx.moveTo(verts[1].x, verts[1].y);
            ctx.lineTo(verts[1].x, verts[1].y + topY);
            ctx.strokeStyle = 'rgba(0,0,0,0.2)';
            ctx.stroke();
        }

        // --- TOP CAP ---
        ctx.save();
        ctx.translate(0, topY);

        ctx.fillStyle = style.light;
        ctx.globalAlpha = 0.9;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();

        // Inner Detail
        ctx.fillStyle = style.detail;
        ctx.beginPath(); ctx.arc(0, 0, r*0.4, 0, Math.PI*2); ctx.fill();

        // Rim
        ctx.strokeStyle = style.highlight;
        ctx.lineWidth = 1;
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.stroke();

        ctx.restore();
    },

    // New: Organic Rock Cluster
    drawIsoRockCluster(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {

        const drawRock = (x: number, y: number, r: number, h: number, seed: number) => {
            ctx.save();
            ctx.translate(x, y);

            // Generate jagged polygon
            const points = [];
            const segments = 7;
            for(let i=0; i<segments; i++) {
                const angle = (i / segments) * Math.PI * 2 + seed;
                const dist = r * (0.8 + Math.sin(angle * 3 + seed) * 0.2);
                points.push({
                    x: Math.cos(angle) * dist,
                    y: Math.sin(angle) * dist * ISO_SCALE_Y
                });
            }

            // Draw Side Faces (Simulated by drawing simplified quads down)
            const topY = -h;
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            points.forEach((p, i) => {
                if (i === 0) ctx.moveTo(p.x, p.y);
                else ctx.lineTo(p.x, p.y);
            });
            ctx.closePath();
            ctx.fill(); // Base

            // Extrude sides
            points.forEach((p, i) => {
                const next = points[(i + 1) % segments];
                // Simple lighting based on angle
                const midAngle = (i / segments) * Math.PI * 2;
                const isLit = midAngle > Math.PI && midAngle < Math.PI * 2; // Right/Bottom lit? No, usually Top/Left lit.

                // Let's use a simpler heuristic: Front faces are lit, Back are dark
                // But here we draw all because of Painter's algo order issues inside the shape.
                // Actually, just drawing a solid block with a top cap is easier.

                ctx.fillStyle = isLit ? style.main : style.dark;
                if (p.y > 0 || next.y > 0) { // Only draw front-ish faces
                    ctx.beginPath();
                    ctx.moveTo(p.x, p.y);
                    ctx.lineTo(next.x, next.y);
                    ctx.lineTo(next.x, next.y + topY);
                    ctx.lineTo(p.x, p.y + topY);
                    ctx.fill();
                }
            });

            // Draw Top Cap (Irregular)
            ctx.translate(0, topY);
            ctx.fillStyle = style.light;
            ctx.beginPath();
            points.forEach((p, i) => {
                if (i === 0) ctx.moveTo(p.x, p.y);
                else ctx.lineTo(p.x, p.y);
            });
            ctx.closePath();
            ctx.fill();

            // Highlight Edge
            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.stroke();

            // Detail cracks
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(r*0.5, r*0.2);
            ctx.strokeStyle = style.dark;
            ctx.stroke();

            ctx.restore();
        };

        // Draw 3 Rocks clustered
        // Big one
        drawRock(5, 5, 22, 25, 0.5);
        // Medium
        drawRock(-15, 0, 16, 18, 2.1);
        // Small
        drawRock(10, 15, 12, 12, 4.3);
    },

    drawIsoPillar(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        // Dynamic Height: Increased to 4.5 to be imposing
        const height = BLOCK_HEIGHT * 4.5;
        const r = HEX_SIZE * 0.7; // Thinner than tile
        const topY = -height;

        const verts = HexGeometry.getVertices(r, true, layout);

        if (layout === 'FLAT') {
            this.drawQuad(ctx, verts[3], verts[2], topY, style.dark);  // Left
            this.drawQuad(ctx, verts[2], verts[1], topY, style.main);  // Front
            this.drawQuad(ctx, verts[1], verts[0], topY, style.light); // Right
        } else {
            // Pointy Pillar (Diamond facing front)
            this.drawQuad(ctx, verts[2], verts[1], topY, style.dark); // Left Face
            this.drawQuad(ctx, verts[1], verts[0], topY, style.main); // Right Face
        }

        // Rune / Sigil
        ctx.save();
        ctx.translate(0, topY / 2); // Center of pillar height
        ctx.strokeStyle = style.detail;
        ctx.lineWidth = 2;
        ctx.shadowColor = style.detail;
        ctx.shadowBlur = 5;

        if (layout === 'FLAT') {
            ctx.beginPath();
            ctx.moveTo(0, -15); ctx.lineTo(0, 15);
            ctx.moveTo(-5, 0); ctx.lineTo(5, 0);
            ctx.stroke();
        } else {
            ctx.beginPath();
            ctx.moveTo(0, -20); ctx.lineTo(0, 20);
            ctx.moveTo(0, -10); ctx.lineTo(verts[0].x * 0.3, -5); 
            ctx.stroke();
        }
        ctx.restore();

        // Top Cap
        ctx.save();
        ctx.translate(0, topY);
        ctx.fillStyle = '#000';
        HexGeometry.traceHex(ctx, 0, 0, r, true, layout);
        ctx.fill();
        ctx.restore();
    },

    drawIsoTree(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout) {
        const trunkW = 14;
        const trunkH = BLOCK_HEIGHT * 1.0;

        ctx.fillStyle = '#3f2e1e';
        ctx.beginPath();
        // Simple trunk
        ctx.fillRect(-trunkW/2, -trunkH, trunkW, trunkH + 5); 

        const layers = 3;
        const baseWidth = layout === 'FLAT' ? HEX_SIZE : HEX_SIZE * 0.9;
        // Layers scale boosted to 2.0 to avoid stubby trees
        const layerHeight = BLOCK_HEIGHT * 2.0; 
        let currentY = -trunkH + 5;

        for (let i = 0; i < layers; i++) {
            const ratio = 1 - (i / layers);
            const width = baseWidth * (0.6 + ratio * 0.4);
            const height = layerHeight;

            ctx.beginPath();
            ctx.moveTo(0, currentY - height); // Top tip

            if (layout === 'FLAT') {
                // Wide Triangle
                ctx.lineTo(width/2, currentY);
                ctx.quadraticCurveTo(0, currentY + 8, -width/2, currentY);
            } else {
                // Sharper Triangle
                ctx.lineTo(width/2, currentY);
                ctx.lineTo(0, currentY + 5); // Pointy dip
                ctx.lineTo(-width/2, currentY);
            }

            ctx.closePath();

            const grad = ctx.createLinearGradient(0, currentY - height, 0, currentY);
            grad.addColorStop(0, style.highlight);
            grad.addColorStop(0.5, style.main);
            grad.addColorStop(1, style.dark);
            ctx.fillStyle = grad;
            ctx.fill();

            ctx.strokeStyle = style.dark;
            ctx.lineWidth = 1;
            ctx.stroke();

            currentY -= (height * 0.7); // Overlap
        }
    },

    drawIsoCrystal(ctx: CanvasRenderingContext2D, style: any, layout: HexLayout, alpha: number = 1.0) {
        // Boosted base height for crystals
        const baseH = BLOCK_HEIGHT * 2.5;

        const drawShard = (x: number, y: number, w: number, h: number, tilt: number) => {
            ctx.save();
            ctx.translate(x, y);
            ctx.rotate(tilt);

            ctx.fillStyle = style.dark;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(-w, -h * 0.2);
            ctx.lineTo(0, -h); 
            ctx.lineTo(w, -h * 0.3);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = style.light;
            ctx.globalAlpha = alpha * 0.6;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(w, -h * 0.3);
            ctx.lineTo(0, -h);
            ctx.fill();

            ctx.strokeStyle = style.highlight;
            ctx.lineWidth = 1;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(0, 0); ctx.lineTo(0, -h);
            ctx.stroke();

            ctx.restore();
        };

        if (layout === 'FLAT') {
            drawShard(-10, 5, 10, baseH * 0.8, -0.2);
            drawShard(10, 2, 12, baseH * 0.6, 0.2);
            drawShard(0, 8, 18, baseH * 1.1, 0); 
        } else {
            drawShard(0, 5, 15, baseH * 1.0, 0); 
            drawShard(-8, 0, 8, baseH * 0.6, -0.15);
            drawShard(8, 0, 8, baseH * 0.6, 0.15);
        }
    },

    // --- Helpers ---
    drawQuad(ctx: CanvasRenderingContext2D, vBottom: {x:number, y:number}, vNextBottom: {x:number, y:number}, topY: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(vBottom.x, vBottom.y);
        ctx.lineTo(vNextBottom.x, vNextBottom.y);
        ctx.lineTo(vNextBottom.x, vNextBottom.y + topY);
        ctx.lineTo(vBottom.x, vBottom.y + topY);
        ctx.closePath();
        ctx.fill();
    },

    drawEdge(ctx: CanvasRenderingContext2D, vBottom: {x:number, y:number}, vNextBottom: {x:number, y:number}, topY: number, color: string) {
        ctx.strokeStyle = 'rgba(255,255,255,0.1)'; // Subtle edge
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(vBottom.x, vBottom.y);
        ctx.lineTo(vBottom.x, vBottom.y + topY);
        ctx.stroke();
    }
};

import { GameEngine } from "../../game";
import { MapSystem } from "../map";
import { SCENE_DB } from "../../../data/scenes";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT, MAX_TERRAIN_TIER } from "../../../constants";

export class MapGenerator {
    public static randomize(system: MapSystem, engine: GameEngine) {
        const layout = engine.mapConfig.layout;
        let cols, rows;

        if (layout === 'FLAT') {
            cols = 8 + Math.floor(Math.random() * 2); 
            rows = 10 + Math.floor(Math.random() * 2); 
        } else {
            cols = 7 + Math.floor(Math.random() * 2); 
            rows = 12 + Math.floor(Math.random() * 2); 
        }

        engine.mapConfig.w = cols; 
        engine.mapConfig.h = rows; 
        engine.currentScene = SCENE_DB[Math.floor(Math.random() * SCENE_DB.length)];
        this.rebuild(system, engine);
    }

    public static rebuild(system: MapSystem, engine: GameEngine) {
        system.resetData();
        const W = engine.mapConfig.w;
        const H = engine.mapConfig.h;
        const tiers = new Map<string, number>();

        const centerQ = Math.floor((W - 1) / 2);
        const centerR = Math.floor((H - 1) / 2);
        const centerHex = { q: centerQ, r: centerR };

        // 用於計算前景深度的參考值
        const centerSum = centerQ + centerR;

        const noisePhaseA = Math.random() * 1000;
        const noisePhaseB = Math.random() * 1000;

        for (let q = 0; q < W; q++) {
            for (let r = 0; r < H; r++) {
                const k = HexUtils.key({q, r});
                system.registerTile(q, r);

                const dist = HexUtils.dist({q, r}, centerHex);

                // 核心數學：階梯狀高度函數 (Stepped Height Field)
                let rawVal = (Math.sin((q + noisePhaseA) * 0.45) + Math.cos((r + noisePhaseB) * 0.45)) * 3.5;

                // Steeper bowl edges
                rawVal += (dist * 0.8); 

                // 視覺修正：前景壓低 (防止遮擋戰場視線)
                const visualDepth = (q + r) - centerSum;
                if (visualDepth > 0) {
                    rawVal -= (visualDepth * 0.8); 
                    if (dist > 3) rawVal -= (dist * 0.3);
                }

                // 離散化為 Tier 層級
                let tier = Math.round(rawVal);
                tier = Math.max(0, Math.min(MAX_TERRAIN_TIER, tier));

                // 確保中心區域平坦
                if (dist < 1.5) tier = 0;

                tiers.set(k, tier);
            }
        }

        // 高度場平滑
        const smoothedTiers = new Map<string, number>();
        tiers.forEach((tier, key) => {
            const [q, r] = key.split(',').map(Number);
            const neighbors = HexUtils.neighbors({q, r});
            let minN = tier;
            neighbors.forEach(n => {
                const nk = HexUtils.key(n);
                if (tiers.has(nk)) minN = Math.min(minN, tiers.get(nk)! + 1);
            });
            smoothedTiers.set(key, minN);
        });

        smoothedTiers.forEach((tier, key) => {
            system.setHeight(key, tier * BLOCK_HEIGHT);
        });

        this.generateDecorations(system, engine, W, H);
        engine.mapVersion++;
        if (engine.renderer) engine.renderer.grid.reset();
    }

    private static generateDecorations(system: MapSystem, engine: GameEngine, W: number, H: number) {
        const obstacleType = engine.currentScene.obstacleStyle || 'WALL';
        const centerHex = { q: Math.floor(W/2), r: Math.floor(H/2) };
        const keys = Array.from(system.getMapKeys());

        // Tuned Density per Biome
        let density = 0.3;
        let noiseThreshold = 0.4;

        if (engine.currentScene.textureType === 'FOREST') {
            density = 0.45; // Denser Forest
            noiseThreshold = 0.2; // Clumpier
        } else if (engine.currentScene.textureType === 'DESERT') {
            density = 0.4; // Scattered Rocks
            noiseThreshold = 0.3;
        }

        keys.forEach((key) => {
            const [q, r] = key.split(',').map(Number);
            const dist = HexUtils.dist({q, r}, centerHex);

            // Leave center clear for fighting
            if (dist < 2.5) return; 

            if (engine.getAgentAt(q, r)) return;

            const noise = Math.sin(q * 0.8) * Math.cos(r * 0.8);
            if (noise > noiseThreshold && Math.random() < density) {
                system.setObstacle(q, r, obstacleType);
            }
        });
    }
}

import { ISO_SCALE_Y, BASE_HEIGHT, BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { HexLayout } from "../../../types";

// 幾何常數
const PEDESTAL_DEPTH = 30; 
const EXPANSION_BIAS = 0.6; // 數學膨脹量 (px)，解決縫隙

export const TerrainRenderer = {
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number,
        layout: HexLayout
    ) {
        // 1. 物理座標取整
        const drawX = Math.floor(x);

        // 2. 呼吸戰場算法 (Biome Selective)
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';

        let floatOffset = 0;
        if (isFloatingBiome) {
            floatOffset = Math.sin(globalTime * 1.5 + (x * 0.01) + (y * 0.01)) * 4;
        }

        // 3. 視覺頂面 Y 軸 (相對於 drawY)
        const visualTopY = -Math.floor(height) + floatOffset;
        const drawY = Math.floor(y);

        // 膨脹幾何半徑
        const r = size + EXPANSION_BIAS;
        const vertices = HexGeometry.getVertices(r, true, layout); 

        ctx.save();
        ctx.translate(drawX, drawY);

        // 4. 繪製基座與側牆 (Pedestal & Walls)
        const drawFace = (idx1: number, idx2: number, color: string, isLightSide: boolean) => {
            const v1 = vertices[idx1];
            const v2 = vertices[idx2];

            // 漸層側牆 (增加立體感)
            const grad = ctx.createLinearGradient(0, visualTopY, 0, PEDESTAL_DEPTH);
            grad.addColorStop(0, color);
            grad.addColorStop(1, isLightSide ? theme.sideDark : '#020617'); // 底部漸黑，融入背景

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY); // Top-Left
            ctx.lineTo(v2.x, v2.y + visualTopY); // Top-Right
            ctx.lineTo(v2.x, v2.y + PEDESTAL_DEPTH); // Bottom-Right (Deep)
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH); // Bottom-Left (Deep)
            ctx.closePath();
            ctx.fill();

            // 側邊高光稜線 (Rim Light)
            ctx.strokeStyle = 'rgba(255,255,255,0.08)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v1.x, v1.y + PEDESTAL_DEPTH);
            ctx.stroke();

            // 頂部接縫高光
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y + visualTopY);
            ctx.lineTo(v2.x, v2.y + visualTopY);
            ctx.strokeStyle = 'rgba(255,255,255,0.15)';
            ctx.stroke();
        };

        if (layout === 'FLAT') {
            drawFace(1, 0, theme.sideDark, false);  // Right-Bottom
            drawFace(2, 1, theme.sideLight, true); // Bottom (Lightest)
            drawFace(3, 2, theme.sideDark, false);  // Left-Bottom
        } else {
            drawFace(1, 0, theme.sideDark, false);  // Right Side
            drawFace(2, 1, theme.sideLight, true); // Left Side
        }

        // 5. 繪製頂部 (Top Cap)
        ctx.translate(0, visualTopY);

        // 頂面材質光澤
        const topGrad = ctx.createLinearGradient(-r, -r, r, r);
        topGrad.addColorStop(0, theme.rim); 
        topGrad.addColorStop(0.3, theme.top);
        topGrad.addColorStop(1, theme.sideDark); 

        ctx.fillStyle = topGrad;
        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // 頂部描邊 (Rim)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5; // 加粗一點
        ctx.globalAlpha = 0.6;
        ctx.stroke();

        // 6. 特殊地表 (岩漿流動)
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0, layout);
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, 
        height: number,
        type: string, 
        detailColor: string, // Usually theme.detail
        q: number, r: number,
        globalTime: number = 0,
        layout: HexLayout = 'FLAT',
        theme: any // Pass full theme for access to sideDark/rim if needed
    ) {
        // Biome Check for details too
        const isFloatingBiome = type === 'VOID' || type === 'MAGMA';

        let floatOffset = 0;
        if (isFloatingBiome) {
            floatOffset = Math.sin(globalTime * 1.5 + (baseX * 0.01) + (baseY * 0.01)) * 4;
        }

        const visualY = Math.floor(baseY) - Math.floor(height) + floatOffset;

        if (type === 'FOREST') {
            // Procedural Grass
            // [VISUAL UPDATE] Use theme.top to blend seamlessly with the block face.
            // SurfacePainter handles the shadowing/variation to make it visible.
            SurfacePainter.drawGrass(ctx, baseX, visualY, theme.top || '#14532d', 5, globalTime);
        } else if (type === 'ICE') {
            // Specular Ice
            SurfacePainter.drawIceSheen(ctx, baseX, visualY, HEX_SIZE, globalTime, layout);
        } else if (type === 'DESERT') {
            // Sand Ripples
            SurfacePainter.drawSandRipples(ctx, baseX, visualY, HEX_SIZE, theme.sideDark || '#92400e');
        } else if (type === 'VOID') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { SceneTheme } from "../../types";
import { HEX_SIZE } from "../../constants";
import { AssetManager } from "../assets";
import { MapConfig } from "../utils";
import { createCanvas } from "../graphics/CanvasUtils";
import { VFXFactory } from "../graphics/VFXFactory";

export class BackgroundRenderer {
    private staticCache: HTMLCanvasElement | null = null;
    private lastSceneId: string = "";
    private lastWidth: number = 0;
    private lastHeight: number = 0;

    public draw(
        ctx: CanvasRenderingContext2D, 
        width: number, 
        height: number, 
        scene: SceneTheme, 
        mapConfig: MapConfig, 
        globalTime: number
    ): void {
        // 1. Rebuild Static Background Layer (Gradient + Stars + Mountains)
        if (!this.staticCache || this.lastSceneId !== scene.id || this.lastWidth !== width || this.lastHeight !== height) {
            this.updateStaticCache(width, height, scene);
        }

        // 2. Draw Static Layer
        if (this.staticCache) {
            ctx.drawImage(this.staticCache, 0, 0);
        }

        // 3. Draw Dynamic Atmospheric Elements
        this.drawDynamicElements(ctx, width, height, scene, mapConfig, globalTime);
    }

    private hexToRgba(hex: string, alpha: number): string {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        return `rgba(${parseInt(result[1], 16)}, ${parseInt(result[2], 16)}, ${parseInt(result[3], 16)}, ${alpha})`;
    }

    private updateStaticCache(w: number, h: number, scene: SceneTheme) {
        if (!this.staticCache) {
            const { canvas } = createCanvas(w, h);
            this.staticCache = canvas;
        } else {
            this.staticCache.width = w;
            this.staticCache.height = h;
        }

        this.lastSceneId = scene.id;
        this.lastWidth = w;
        this.lastHeight = h;

        const ctx = this.staticCache.getContext('2d')!;
        ctx.clearRect(0, 0, w, h);

        // A. Deep Background Gradient (Richer)
        const bgGrad = ctx.createLinearGradient(0, 0, 0, h);
        bgGrad.addColorStop(0, scene.background);
        bgGrad.addColorStop(0.4, scene.fogColor); 
        bgGrad.addColorStop(1, scene.horizon); 
        ctx.fillStyle = bgGrad;
        ctx.fillRect(0, 0, w, h);

        // B. Scene Specific Static Features
        if (scene.bgFeature === 'SKY_RIVER') {
            this.drawStaticSkyRiver(ctx, w, h);
        } else {
            this.drawStaticStars(ctx, w, h, 150); // More stars
        }

        // C. Distant Grid (Retro-wave floor)
        // Draw grid BEFORE horizon seam so seam covers it
        this.drawPerspectiveGrid(ctx, w, h, scene.horizon);

        // D. Mountains / Dunes
        if (scene.bgFeature === 'DUNES') {
            this.drawStaticDunes(ctx, w, h, scene.horizon, scene.fogColor);
        } else {
            this.drawStaticMountains(ctx, w, h, scene.horizon, scene.fogColor);
        }

        // E. Horizon Blending Strip (Seam Fix) - Improved Gradient
        // Increased Height to 350 to allow smoother falloff
        const horizonY = h * 0.6;
        const seamHeight = 350; 
        const seamGrad = ctx.createLinearGradient(0, horizonY - seamHeight * 0.6, 0, horizonY + seamHeight * 0.4);

        // [FIX] Using 'screen' or brighter blend modes earlier caused the line. 
        // We use source-over with 100% opacity at the core to physically cover the seam.
        const fogRgbaFull = this.hexToRgba(scene.fogColor, 1.0); // Full opacity at core
        const fogRgbaMid = this.hexToRgba(scene.fogColor, 0.8);
        const fogRgbaZero = this.hexToRgba(scene.fogColor, 0);

        seamGrad.addColorStop(0, fogRgbaZero);
        seamGrad.addColorStop(0.3, fogRgbaMid);
        seamGrad.addColorStop(0.5, fogRgbaFull); 
        seamGrad.addColorStop(0.7, fogRgbaMid);
        seamGrad.addColorStop(1, fogRgbaZero);

        ctx.globalCompositeOperation = 'source-over';
        ctx.fillStyle = seamGrad;
        ctx.fillRect(0, horizonY - seamHeight * 0.6, w, seamHeight);

        // F. Vignette
        const rad = Math.max(w, h);
        const vig = ctx.createRadialGradient(w/2, h/2, rad * 0.4, w/2, h/2, rad * 0.9);
        vig.addColorStop(0, 'rgba(0,0,0,0)');
        vig.addColorStop(1, 'rgba(0,0,0,0.8)'); // Darker vignette
        ctx.fillStyle = vig;
        ctx.fillRect(0, 0, w, h);
    }

    private drawPerspectiveGrid(ctx: CanvasRenderingContext2D, w: number, h: number, color: string) {
        ctx.save();
        ctx.globalAlpha = 0.15; // Slightly clearer
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;

        const horizonY = h * 0.6;
        const centerX = w * 0.5;

        // Vertical lines converging to horizon
        ctx.beginPath();
        for (let x = -w; x < w * 2; x += 100) {
            ctx.moveTo(x, h);
            ctx.lineTo(centerX + (x - centerX) * 0.1, horizonY);
        }
        ctx.stroke();

        // Horizontal lines - With Fadeout near horizon
        // [FIX] Start fading out earlier (0.2 instead of 0.15) to ensure zero overlap with sky
        for (let y = h; y > horizonY; y -= (y - horizonY) * 0.1 + 2) {
            // Distance Factor (0 at horizon, 1 at bottom)
            const dist = (y - horizonY) / (h - horizonY);
            if (dist < 0.2) continue; 

            ctx.globalAlpha = 0.15 * Math.pow(dist, 0.5); // Fade out as it goes back
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(w, y);
            ctx.stroke();
        }

        ctx.restore();
    }

    private drawStaticStars(ctx: CanvasRenderingContext2D, w: number, h: number, count: number) {
        ctx.fillStyle = '#fff';
        const seed = 123;
        for(let i=0; i<count; i++) {
            const sx = (Math.sin(i * seed) * 0.5 + 0.5) * w;
            const sy = (Math.cos(i * seed * 1.5) * 0.5 + 0.5) * h * 0.7;
            const size = Math.random() * 1.8;
            const alpha = Math.random() * 0.6 + 0.2;
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.arc(sx, sy, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.globalAlpha = 1.0;
    }

    private drawStaticSkyRiver(ctx: CanvasRenderingContext2D, w: number, h: number) {
        ctx.save();
        const grad = ctx.createLinearGradient(0, 0, w, h * 0.8);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.3, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(0.5, 'rgba(124, 58, 237, 0.25)');
        grad.addColorStop(0.7, 'rgba(79, 70, 229, 0.15)');
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.moveTo(0, h*0.2);
        ctx.quadraticCurveTo(w*0.5, h*0.5, w, h*0.4);
        ctx.lineTo(w, h*0.7);
        ctx.quadraticCurveTo(w*0.5, h*0.8, 0, h*0.5);
        ctx.fill();

        this.drawStaticStars(ctx, w, h, 200);
        ctx.restore();
    }

    private drawStaticMountains(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawLayer = (yOffset: number, color: string, roughness: number, seedOffset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, h * 0.6 + yOffset);
            for(let x=0; x<=w; x+=20) {
                const n = Math.sin(x * 0.01 + seedOffset) * Math.cos(x * 0.03) * roughness;
                ctx.lineTo(x, h * 0.6 + yOffset + n);
            }
            ctx.lineTo(w, h * 0.6 + yOffset);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.3;
        drawLayer(0, colorFar, 60, 0);

        ctx.globalAlpha = 0.5;
        drawLayer(60, colorNear, 40, 100);
        ctx.globalAlpha = 1.0;
    }

    private drawStaticDunes(ctx: CanvasRenderingContext2D, w: number, h: number, colorFar: string, colorNear: string) {
        const drawDune = (yBase: number, color: string, amp: number, freq: number, offset: number) => {
            ctx.fillStyle = color;
            ctx.beginPath();
            ctx.moveTo(0, h);
            ctx.lineTo(0, yBase);
            for(let x=0; x<=w; x+=30) {
                const y = yBase + Math.sin(x * freq + offset) * amp;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, yBase);
            ctx.lineTo(w, h);
            ctx.fill();
        };

        ctx.globalAlpha = 0.4;
        drawDune(h * 0.65, colorFar, 30, 0.005, 0);

        ctx.globalAlpha = 0.6;
        drawDune(h * 0.75, colorNear, 40, 0.003, 2);
        ctx.globalAlpha = 1.0;
    }

    // --- DYNAMIC RENDERING ---

    private drawDynamicElements(ctx: CanvasRenderingContext2D, w: number, h: number, scene: SceneTheme, mapConfig: MapConfig, t: number) {
        ctx.save();

        // 1. Drifting Particles (New Layer)
        // Draw some random floating specks
        ctx.fillStyle = scene.ambientColor;
        const speckCount = 50;
        for(let i=0; i<speckCount; i++) {
            const speed = (i % 5 + 1) * 10;
            const y = (h + (i * 53) - (t * speed)) % h;
            const x = (w + (i * 97) + Math.sin(t + i)*50) % w;
            const size = Math.sin(t * 2 + i) + 2;

            ctx.globalAlpha = (Math.sin(t + i) * 0.5 + 0.5) * 0.6;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }

        // 2. Horizon Glow
        const glowH = h * 0.7;
        const pulse = 1.0 + Math.sin(t * 0.5) * 0.1;
        const horizonGrad = ctx.createRadialGradient(w/2, glowH, w * 0.2, w/2, glowH, w * 0.8 * pulse);
        horizonGrad.addColorStop(0, scene.horizon);
        horizonGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.3;
        ctx.fillStyle = horizonGrad;
        ctx.fillRect(0, h/2, w, h/2);

        // 3. Features
        if (scene.bgFeature === 'AURORA') {
            this.drawAurora(ctx, w, h, t);
        } else if (scene.bgFeature === 'CANOPY') {
            this.drawCanopyRays(ctx, w, h, t);
        } else if (scene.bgFeature === 'HEAT_WAVE') {
            this.drawHeatHaze(ctx, w, h, t, scene.horizon);
        }

        // 4. Fog / Atmospheric Effects
        if (scene.textureType === 'DESERT') {
            this.drawSandStorm(ctx, w, h, t, scene.fogColor);
        } else {
            this.drawFogLayers(ctx, w, h, scene.fogColor, mapConfig, t);
        }

        ctx.restore();
    }

    private drawAurora(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const numBands = 3;
        const baseH = h * 0.4;

        for (let i = 0; i < numBands; i++) {
            const speed = t * 0.2 + i;
            ctx.beginPath();
            ctx.moveTo(0, baseH);
            for (let x = 0; x <= w; x += 50) {
                const y = baseH + Math.sin(x * 0.005 + speed) * 50 + Math.sin(x * 0.02 - speed) * 20;
                ctx.lineTo(x, y);
            }
            ctx.lineTo(w, 0);
            ctx.lineTo(0, 0);

            const grad = ctx.createLinearGradient(0, 0, w, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, `hsla(170, 80%, 60%, 0.15)`); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.fill();
        }
    }

    private drawCanopyRays(ctx: CanvasRenderingContext2D, w: number, h: number, t: number) {
        ctx.globalCompositeOperation = 'overlay';
        const raySprite = VFXFactory.getTexture('BEAM', 'rgba(255,255,255,0.1)');

        const numRays = 4;
        for (let i = 0; i < numRays; i++) {
            const angle = Math.sin(t * 0.2 + i) * 0.1 + 0.6;
            const x = w * (0.2 + i * 0.2) + Math.sin(t * 0.1) * 50;

            ctx.save();
            ctx.translate(x, -100);
            ctx.rotate(angle);
            ctx.globalAlpha = 0.15 + Math.sin(t * 0.5 + i) * 0.05;
            ctx.drawImage(raySprite, -50, 0, 100, h * 1.5);
            ctx.restore();
        }
    }

    private drawHeatHaze(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'screen';
        const grad = ctx.createLinearGradient(0, h, 0, h * 0.6);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');

        ctx.globalAlpha = 0.2 + Math.sin(t * 2) * 0.05;
        ctx.fillStyle = grad;
        ctx.fillRect(0, h * 0.6, w, h * 0.4);

        ctx.globalAlpha = 0.05;
        ctx.fillStyle = '#fff';
        const bands = 5;
        for(let i=0; i<bands; i++) {
            const y = h - ((t * 50 + i * 100) % (h*0.4));
            ctx.fillRect(0, y, w, 10);
        }
    }

    private drawFogLayers(ctx: CanvasRenderingContext2D, w: number, h: number, color: string, mapConfig: MapConfig, t: number) {
        ctx.globalCompositeOperation = 'screen';
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 4;

        for (let i = 0; i < numClouds; i++) {
            const speed = 25;
            const x = ((t * speed + i * (w / numClouds)) % (w + 400)) - 200;
            const y = h * 0.6 + Math.sin(i + t * 0.2) * 50;
            const size = 400;

            ctx.globalAlpha = 0.08; 
            ctx.drawImage(fogSprite, x - size/2, y - size/2, size, size * 0.5);
        }
    }

    private drawSandStorm(ctx: CanvasRenderingContext2D, w: number, h: number, t: number, color: string) {
        ctx.globalCompositeOperation = 'overlay'; 

        const windSpeed = 300; // Increased wind speed
        const drift = t * windSpeed;

        // 1. Base Dust Haze
        const grad = ctx.createLinearGradient(0, 0, w, 0);
        grad.addColorStop(0, 'rgba(0,0,0,0)');
        grad.addColorStop(0.5, color);
        grad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.2; 
        ctx.fillRect(0, 0, w, h);

        // 2. Flying Sand Clouds (Midground)
        const fogSprite = AssetManager.getFogCloud(color);
        const numClouds = 6;
        for (let i = 0; i < numClouds; i++) {
            const x = ((drift + i * (w / numClouds)) % (w + 600)) - 300;
            const y = (Math.sin(i * 132 + t) * 0.5 + 0.5) * h;
            const size = 500;

            ctx.globalAlpha = 0.12;
            ctx.drawImage(fogSprite, x, y, size, size * 0.3);
        }

        // 3. Low Ground Mist (NEW) - Flowing sand near the floor
        const mistH = 200;
        const mistY = h - mistH;

        const mistGrad = ctx.createLinearGradient(0, mistY, 0, h);
        mistGrad.addColorStop(0, 'rgba(0,0,0,0)');
        mistGrad.addColorStop(0.4, color);
        mistGrad.addColorStop(1, 'rgba(0,0,0,0.8)');

        ctx.fillStyle = mistGrad;
        ctx.globalAlpha = 0.4 + Math.sin(t*3) * 0.1;
        ctx.fillRect(0, mistY, w, mistH);

        // Fast moving noise layer in the mist
        const noiseX = (drift * 1.5) % 100;
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.05;
        for(let i=0; i<10; i++) {
            const barH = 5 + Math.random()*10;
            const barY = h - 50 - Math.random() * 100;
            ctx.fillRect(0, barY, w, barH);
        }

        // 4. Fast Streaks (Foreground Wind)
        ctx.strokeStyle = '#fff';
        ctx.globalAlpha = 0.08;
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let i = 0; i < 30; i++) {
            // Skew streaks to look like they are flying over the grid
            const streakX = ((drift * 2.5 + i * 153) % (w + 200)) - 100;
            const streakY = (Math.sin(i * 21) * 0.5 + 0.5) * (h * 0.8) + h * 0.2; // Keep lower on screen
            ctx.moveTo(streakX, streakY);
            ctx.lineTo(streakX + 150, streakY + 5);
        }
        ctx.stroke();
    }
}

import { VFXStateManager } from "./state";

export class VFXAmbience {
    private timer: number = 0;

    public update(dt: number, type: string, state: VFXStateManager) {
        if (type === 'NONE') return;

        this.timer += dt;

        // Rate Control:
        // Snow/Ash/Sand: Frequent spawn (Dense atmosphere)
        // Others: Sparse spawn
        let rate = 0.15;
        if (type === 'SNOW' || type === 'ASH') rate = 0.03;
        if (type === 'SAND') rate = 0.005; // Extremely fast spawn for dense sand

        if (this.timer > rate) {
            this.timer = 0;

            const p = state.getParticle();
            p.type = 'ATMOSPHERE'; 

            // Default random spawn logic (overridden for Sand)
            let x = Math.random() * 1600 - 200;
            const y = Math.random() * 1000 - 200;

            // Randomize Z for parallax feeling
            p.z = Math.random() * 400 + 50; 

            if (type === 'SNOW') {
                p.x = x; p.y = y;
                p.color = '#fff';
                p.size = Math.random() * 2.5 + 1.5;
                p.vx = 40 + Math.random() * 30; // Wind
                p.vy = 80 + Math.random() * 40; // Fall
                p.life = 4.0; p.maxLife = 4.0;
                p.blendMode = 'source-over';
            } else if (type === 'ASH') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#1c1917' : '#451a03'; // Dark Ash
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 30 + Math.random() * 20;
                p.life = 5.0; p.maxLife = 5.0;
                p.blendMode = 'source-over';
            } else if (type === 'EMBER') {
                p.x = x; p.y = y;
                p.color = Math.random() > 0.5 ? '#f59e0b' : '#ef4444';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 40;
                p.vy = -40 - Math.random() * 30; // Rise
                p.life = 2.5; p.maxLife = 2.5;
                p.blendMode = 'screen'; 
            } else if (type === 'SPORES') {
                p.x = x; p.y = y;
                // Mystic floaty particles
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2.5 + 0.5;
                p.vx = (Math.random() - 0.5) * 15;
                p.vy = (Math.random() - 0.5) * 15;
                p.life = 6.0; p.maxLife = 6.0;
                p.blendMode = 'screen';
            } else if (type === 'SAND') {
                // Directional High Speed Sandstorm
                // Spawn off-screen left, fly right
                p.x = -100; 
                p.y = Math.random() * 1200 - 200; // Full vertical coverage

                // Amber/Tan colors
                p.color = Math.random() > 0.6 ? '#fcd34d' : '#d97706'; 
                p.size = Math.random() * 2 + 1; // Slightly larger chunks

                // High horizontal velocity
                p.vx = 1200 + Math.random() * 600; // Extremely Fast
                p.vy = 50 + Math.random() * 30; // Slight fall/drift

                p.life = 1.5; p.maxLife = 1.5; // Short life (moves fast)
                p.blendMode = 'source-over';
            }

            state.particles.push(p);
        }
    }
}
